# -*- coding: utf-8 -*-
"""
Book 33: The Strange Case of Dr. Jekyll and Mr. Hyde - Complete Dataset (25 Pages, 500 Sentences, 200 Vocab)
Robert Louis Stevenson
"""

BOOK_DATA = [{'page_no': 1, 'title': 'Story of the Door', 'tr_title': 'Kapının Hikayesi', 'vocab_focus': [('lawyer', 'avukat'), ('austere', 'ciddi, sert, sade'), ('byway', 'ara sokak, tali yol'), ('trample', 'çiğnemek, ezmek'), ('repulsive', 'itici, iğrenç'), ('cheque', 'banka çeki'), ('blackmail', 'şantaj'), ('deformity', 'şekil bozukluğu, sakatlık')], 'sentences': [{'id': 1, 'text': 'Mr. Gabriel John Utterson was a London lawyer of a rugged countenance that was never lighted by a smile.', 'translation': 'Bay Gabriel John Utterson, yüzü hiçbir zaman bir tebessümle aydınlanmayan sert çehreli bir Londra avukatıydı.', 'notes': 'rugged countenance: sert çehre.'}, {'id': 2, 'text': 'He was cold, dry, tall, and lean, yet somehow deeply lovable and trusted by all his clients.', 'translation': 'Soğuk, kuru, uzun boylu ve zayıftı; fakat bir şekilde son derece sevilebilir ve tüm müvekkillerinin güvendiği biriydi.', 'notes': 'deeply lovable: derinden sevilen.'}, {'id': 3, 'text': 'Every Sunday, he walked through the quiet streets of London with his distant kinsman, Mr. Richard Enfield.', 'translation': "Her pazar günü, uzaktan akrabası olan Bay Richard Enfield ile Londra'nın sessiz sokaklarında yürüyüş yapardı.", 'notes': 'distant kinsman: uzaktan akraba.'}, {'id': 4, 'text': 'During one of their rambles, their path led them down a narrow, shadowy byway in a busy commercial quarter.', 'translation': 'Yürüyüşlerinden birinde yolları, işlek bir ticaret mahallesindeki dar ve gölgeli bir ara sokağa düştü.', 'notes': 'shadowy byway: gölgeli ara sokak.'}, {'id': 5, 'text': 'On one side stood a sinister two-story building that thrust out its blind, windowless wall upon the street.', 'translation': 'Bir yanda, kör ve penceresiz duvarını sokağa doğru uzatan meşum, iki katlı bir bina duruyordu.', 'notes': 'sinister building: meşum/uğursuz bina.'}, {'id': 6, 'text': 'The ancient door was stained, blistered by neglect, and equipped with neither bell nor knocker.', 'translation': 'Eski kapı lekelenmişti, bakımsızlıktan kabarmıştı ve ne bir zili ne de kapı tokmağı vardı.', 'notes': 'blistered by neglect: bakımsızlıktan kabarmış.'}, {'id': 7, 'text': 'Enfield stopped and pointed his walking stick toward the decaying entrance.', 'translation': 'Enfield durdu ve bastonunu o döküntü girişe doğru doğrulttu.', 'notes': 'walking stick: yürüyüş bastonu.'}, {'id': 8, 'text': '"Did you ever remark that strange door, Utterson?" Enfield inquired with a grim expression.', 'translation': '"O garip kapıyı hiç fark etmiş miydin Utterson?" diye sordu Enfield yüzünde asık bir ifadeyle.', 'notes': 'grim expression: asık/ciddi ifade.'}, {'id': 9, 'text': '"It is connected in my mind with a very extraordinary and horrifying story," Enfield continued.', 'translation': '"Zihnimde son derece olağandışı ve dehşet verici bir hikayeyle bağlantılıdır bu kapı," diye devam etti Enfield.', 'notes': 'horrifying story: dehşet verici hikaye.'}, {'id': 10, 'text': '"I was returning home through this neighbourhood at three o\'clock on a black winter morning."', 'translation': '"Karanlık bir kış sabahı saat üçte bu mahalleden geçerek evime dönüyordum."', 'notes': 'black winter morning: karanlık kış sabahı.'}, {'id': 11, 'text': '"Suddenly, I saw two figures: a little girl running for a doctor, and a short man walking rapidly."', 'translation': '"Ansızın iki kişi gördüm: doktor çağırmak için koşan küçük bir kız ve hızla yürüyen kısa boylu bir adam."', 'notes': 'walking rapidly: hızla yürüyen.'}, {'id': 12, 'text': '"They ran into one another at the corner, and then came the horrible part of the encounter."', 'translation': '"Köşede birbirlerine çarptılar ve ardından bu karşılaşmanın korkunç kısmı geldi."', 'notes': 'horrible encounter: korkunç karşılaşma.'}, {'id': 13, 'text': '"The man trampled calmly over the child\'s screaming body and left her weeping in the gutter!"', 'translation': '"Adam çocuğun çığlık atan bedenini sakince çiğneyip geçti ve onu su oluğunda ağlar halde bıraktı!"', 'notes': 'trampled calmly: sakince çiğnedi.'}, {'id': 14, 'text': '"It sounded of nothing human; it was like some damned, unfeeling Juggernaut crushing an insect!"', 'translation': '"İnsani hiçbir yanı yoktu; sanki bir böceği ezen o lanetli, duygusuz devasa bir put gibiydi!"', 'notes': 'unfeeling Juggernaut: duygusuz devasa güç/put.'}, {'id': 15, 'text': '"I caught the fellow by the collar and brought him back to where a furious crowd had gathered."', 'translation': '"Herifi yakasından tuttuğum gibi öfkeli bir kalabalığın toplandığı yere geri getirdim."', 'notes': 'caught by collar: yakasından yakaladı.'}, {'id': 16, 'text': '"We threatened to ruin his reputation across London unless he compensated the poor child\'s family."', 'translation': '"Zavallı çocuğun ailesinin zararını tazmin etmediği takdirde itibarını tüm Londra\'da yerle bir etmekle tehdit ettik."', 'notes': 'ruin reputation: itibarını yerle bir etmek.'}, {'id': 17, 'text': '"He agreed coldly, unlocked that very door with a key, and brought out ten pounds in gold and a cheque."', 'translation': '"Soğukkanlılıkla kabul etti, tam şu kapıyı bir anahtarla açtı ve içeriden on pound altın ile bir çek getirdi."', 'notes': 'agreed coldly: soğukça kabul etti.'}, {'id': 18, 'text': '"To my astonishment, the cheque was genuine and signed by a celebrated, honorable gentleman!"', 'translation': '"Büyük bir şaşkınlıkla gördüm ki çek sahiciydi ve çok ünlü, saygıdeğer bir beyefendi tarafından imzalanmıştı!"', 'notes': 'celebrated gentleman: ünlü/saygın beyefendi.'}, {'id': 19, 'text': '"What was the name of the cruel man who trampled the child?" Utterson asked with sudden gravity.', 'translation': '"Çocuğu çiğneyen o zalim adamın adı neydi?" diye sordu Utterson ani bir ciddiyetle.', 'notes': 'sudden gravity: ani bir ciddiyet.'}, {'id': 20, 'text': '"His name was Edward Hyde," Enfield answered; "a man who radiated an indescribable sense of deformity."', 'translation': '"Adı Edward Hyde idi," diye yanıtladı Enfield; "tarif edilemez bir şekilsizlik ve kötülük hissi yayan bir adam."', 'notes': 'indescribable deformity: tarif edilemez şekilsizlik.'}]}, {'page_no': 2, 'title': 'Search for Mr. Hyde and the Sinister Will', 'tr_title': "Bay Hyde'ı Arayış ve Meşum Vasiyetname", 'vocab_focus': [('benefactor', 'hayırsever, velinimet'), ('disappearance', 'ortadan kaybolma'), ('balderdash', 'saçmalık, zırva'), ('haunt', 'mesken tutmak, sık sık gitmek'), ('dwarfish', 'cüce gibi, ufak tefek'), ('troglodytic', 'mağara adamı gibi, ilkel'), ('hissing', 'tıslama'), ('snarl', 'hırıldama')], 'sentences': [{'id': 21, 'text': 'Mr. Utterson returned to his bachelor home in sombre spirits and sat down in his private study.', 'translation': 'Bay Utterson kasvetli duygular içinde bekar evine döndü ve özel çalışma odasına oturdu.', 'notes': 'sombre spirits: kasvetli ruh hali.'}, {'id': 22, 'text': "He unlocked his iron safe and took out a confidential envelope containing Dr. Henry Jekyll's last will.", 'translation': "Demir kasasını açtı ve Doktor Henry Jekyll'ın son vasiyetnamesini içeren gizli bir zarf çıkardı.", 'notes': 'confidential envelope: gizli zarf.'}, {'id': 23, 'text': "The document stipulated that in case of Jekyll's death, all his worldly goods should pass to Edward Hyde.", 'translation': "Belge, Jekyll'ın ölümü halinde dünyevi tüm mallarının Edward Hyde'a geçmesini şart koşuyordu.", 'notes': 'worldly goods: dünyevi mallar.'}, {'id': 24, 'text': 'Even more alarming, it stated that if Jekyll disappeared for more than three months, Hyde should step into his shoes.', 'translation': "Daha da endişe verici olanı, eğer Jekyll üç aydan fazla ortadan kaybolursa Hyde'ın onun yerine geçeceğini belirtiyordu.", 'notes': 'step into his shoes: onun yerine geçmek.'}, {'id': 25, 'text': 'Utterson had always hated the will, but now that Hyde had proven himself a monster, he feared foul play.', 'translation': "Utterson bu vasiyetnameden her zaman nefret etmişti fakat şimdi Hyde'ın bir canavar olduğu kanıtlanınca bir cinayetten korktu.", 'notes': 'feared foul play: bir cinayetten/kötülükten korktu.'}, {'id': 26, 'text': 'Seeking answers, Utterson visited Dr. Hastie Lanyon, a celebrated physician living in Cavendish Square.', 'translation': "Cevaplar arayan Utterson, Cavendish Meydanı'nda yaşayan ünlü bir hekim olan Doktor Hastie Lanyon'u ziyaret etti.", 'notes': 'celebrated physician: ünlü hekim.'}, {'id': 27, 'text': 'Lanyon welcomed his old friend warmly, but confessed that he had not seen Jekyll for more than ten years.', 'translation': "Lanyon eski dostunu sıcak bir şekilde karşıladı fakat Jekyll'ı on yıldan uzun süredir görmediğini itiraf etti.", 'notes': 'welcomed warmly: sıcakça karşıladı.'}, {'id': 28, 'text': '"Henry became too fanciful for me; he began to go wrong in mind over unscientific balderdash!" Lanyon declared.', 'translation': '"Henry benim için fazla hayalperest oldu; bilim dışı saçmalıklar yüzünden aklı karışmaya başladı!" dedi Lanyon.', 'notes': 'unscientific balderdash: bilim dışı saçmalık.'}, {'id': 29, 'text': 'Lanyon admitted that he had never heard of anyone named Edward Hyde in all his years of acquaintance.', 'translation': 'Lanyon, tüm tanışıklıkları boyunca Edward Hyde adında birini hiç duymadığını kabul etti.', 'notes': 'years of acquaintance: tanışıklık yılları.'}, {'id': 30, 'text': 'That night, Utterson tossed upon his bed, haunted by vivid nightmares of a faceless fiend gliding through London.', 'translation': "O gece Utterson, Londra'da süzülen yüzsüz bir iblisin canlı kâbuslarıyla kıvranarak yatağında bir o yana bir bu yana döndü.", 'notes': 'tossed upon his bed: yatağında kıvrandı/döndü durdu.'}, {'id': 31, 'text': '"If he be Mr. Hyde," the determined lawyer resolved grimly, "then I shall be Mr. Seek!"', 'translation': '"Eğer o Bay Gizlenen (Hyde) ise," diye kararlılıkla ant içti avukat, "o halde ben de Bay Arayan (Seek) olacağım!"', 'notes': 'Mr. Seek: Arayan Bay (kelime oyunu: hide and seek).'}, {'id': 32, 'text': 'From that day onward, Utterson began haunting the narrow byway, waiting beside the mysterious door at all hours.', 'translation': 'O günden itibaren Utterson dar ara sokağı mesken tuttu; günün her saatinde o esrarengiz kapının yanında bekledi.', 'notes': 'haunting the byway: ara sokağı mesken tutmak.'}, {'id': 33, 'text': 'Finally, on a fine, frosty night, he heard light, odd steps approaching through the silence.', 'translation': 'Nihayet ayazlı, berrak bir gecede sessizliğin içinden yaklaşan hafif, tuhaf ayak sesleri duydu.', 'notes': 'light odd steps: hafif tuhaf adımlar.'}, {'id': 34, 'text': 'A small man dressed simply in dark clothes stepped out from the fog and drew a key from his pocket.', 'translation': 'Koyu renkli sade giysiler giymiş ufak tefek bir adam sisin içinden belirdi ve cebinden bir anahtar çıkardı.', 'notes': 'stepped out from fog: sisin içinden çıktı.'}, {'id': 35, 'text': 'Utterson stepped forward and touched him on the shoulder: "Mr. Hyde, I presume?"', 'translation': 'Utterson öne çıktı ve omzuna dokundu: "Sanırım Bay Hyde sizsiniz?"', 'notes': 'I presume: sanırım, öyle tahmin ediyorum.'}, {'id': 36, 'text': 'The small man shrank back with a hissing intake of breath, glaring at the lawyer with fierce suspicion.', 'translation': 'Ufak tefek adam tıslayan bir nefes çekişiyle geriye sindi; şiddetli bir şüpheyle avukata dik dik baktı.', 'notes': 'hissing intake of breath: tıslayarak nefes alma.'}, {'id': 37, 'text': 'His face was pale and dwarfish; he spoke with a husky, whispering voice that sounded troglodytic and primitive.', 'translation': 'Yüzü solgun ve cüce gibiydi; ilkel ve mağara insanı gibi tınlayan boğuk, fısıltılı bir sesle konuşuyordu.', 'notes': 'husky whispering voice: boğuk fısıltılı ses.'}, {'id': 38, 'text': 'He gave an impression of absolute deformity without any distinct, nameable malformation.', 'translation': 'Belirgin, adlandırılabilecek hiçbir sakatlığı olmamasına rağmen mutlak bir biçimsizlik hissi uyandırıyordu.', 'notes': 'impression of deformity: biçimsizlik/çirkinlik hissi.'}, {'id': 39, 'text': 'Hyde gave Utterson an address in Soho, laughed with snarling malice, and slipped swiftly into the house.', 'translation': "Hyde Utterson'a Soho'da bir adres verdi, hırlayan bir kötü niyetle güldü ve hızla evin içine süzüldü.", 'notes': 'snarling malice: hırlayan kötü niyet.'}, {'id': 40, 'text': 'Left alone in the chill air, Utterson shuddered with revulsion, feeling that he had looked upon pure evil.', 'translation': 'Ayaz havada yapayalnız kalan Utterson, saf kötülüğe bakmış olduğunu hissederek tiksintiyle ürperdi.', 'notes': 'shuddered with revulsion: tiksintiyle ürperdi.'}]}, {'page_no': 3, 'title': 'Dr. Jekyll Was Quite at Ease', 'tr_title': 'Doktor Jekyll Gayet Rahattı', 'vocab_focus': [('butler', 'baş uşak'), ('laboratory', 'laboratuvar'), ('hearth', 'şömine, ocak'), ('benefactor', 'velinimet, koruyucu'), ('unbearable', 'katlanılmaz, dayanılmaz'), ('pledge', 'söz vermek, taahhüt etmek'), ('dissolving', 'çözülme, erime'), ('discretion', 'tedbir, ketumluk')], 'sentences': [{'id': 41, 'text': "Utterson walked around the corner to the grand facade of Dr. Henry Jekyll's square residence.", 'translation': "Utterson köşeyi dönerek Doktor Henry Jekyll'ın meydandaki malikanesinin görkemli ön cephesine yürüdü.", 'notes': 'grand facade: görkemli ön cephe.'}, {'id': 42, 'text': 'The elderly butler, Poole, opened the door and admitted the lawyer into a comfortable, firelit hall.', 'translation': 'Yaşlı uşak Poole kapıyı açtı ve avukatı şömine ışığıyla aydınlanan konforlu bir salona buyur etti.', 'notes': 'firelit hall: şömineyle aydınlanan salon.'}, {'id': 43, 'text': 'Utterson asked if Mr. Edward Hyde had entered the house through the old surgical dissection theater.', 'translation': "Utterson, Bay Edward Hyde'ın eve eski cerrahi anatomi salonundan girip girmediğini sordu.", 'notes': 'dissection theater: anatomi/teşrih salonu.'}, {'id': 44, 'text': '"Quite right, Mr. Utterson," Poole replied respectfully; "Mr. Hyde has a key to the laboratory."', 'translation': '"Aynen öyle Bay Utterson," diye yanıtladı Poole saygıyla; "Bay Hyde\'ın laboratuvarın anahtarı var."', 'notes': 'replied respectfully: saygıyla yanıtladı.'}, {'id': 45, 'text': '"We have all received strict orders from the master to obey Mr. Hyde as if he were Dr. Jekyll himself."', 'translation': '"Hepimiz efendimizden, sanki bizzat Doktor Jekyll\'ın kendisiymiş gibi Bay Hyde\'a itaat etmemiz yönünde kesin emirler aldık."', 'notes': 'strict orders: kesin emirler.'}, {'id': 46, 'text': 'Utterson departed, convinced that his noble friend was being blackmailed for some dark transgression of his youth.', 'translation': 'Asil dostunun gençliğindeki karanlık bir günah yüzünden şantaja uğradığına ikna olan Utterson oradan ayrıldı.', 'notes': 'dark transgression: karanlık günah/kusur.'}, {'id': 47, 'text': 'Two weeks later, Dr. Jekyll hosted a delightful dinner party for five or six of his oldest cronies.', 'translation': 'İki hafta sonra Doktor Jekyll en eski dostlarından beş altı kişi için nefis bir akşam yemeği partisi verdi.', 'notes': 'oldest cronies: en eski yakın dostlar.'}, {'id': 48, 'text': 'When the other guests had departed, Utterson lingered behind by the warm hearth to speak with Jekyll alone.', 'translation': 'Diğer misafirler ayrıldığında Utterson Jekyll ile baş başa konuşmak için sıcak şöminenin başında oyalandı.', 'notes': 'lingered behind: geride oyalandı.'}, {'id': 49, 'text': 'Dr. Jekyll was a large, well-made, smooth-faced man of fifty, with every mark of capacity and kindness.', 'translation': 'Doktor Jekyll elli yaşlarında, iri yapılı, düzgün yüzlü ve üzerinde her türlü yetenek ve nezaket işareti taşıyan bir adamdı.', 'notes': 'smooth-faced man: pürüzsüz/düzgün yüzlü adam.'}, {'id': 50, 'text': '"I have been wanting to speak to you, Jekyll," Utterson began seriously; "it is concerning your will."', 'translation': '"Seninle konuşmak istiyordum Jekyll," diye ciddi bir şekilde başladı Utterson; "mesele vasiyetnamenle ilgili."', 'notes': 'concerning your will: vasiyetnamene dair.'}, {'id': 51, 'text': "A cloud passed over Jekyll's handsome face, and his warm eyes grew cold and defensive.", 'translation': "Jekyll'ın yakışıklı yüzünden bir bulut geçti ve sıcak gözleri soğuk ve savunmacı bir hal aldı.", 'notes': 'cloud passed over: yüzünden bulut geçti.'}, {'id': 52, 'text': '"My dear Utterson, you know you cannot change my mind on that matter," Jekyll replied with a forced smile.', 'translation': '"Sevgili Utterson, o konuda fikrimi değiştiremeyeceğini biliyorsun," diye yanıtladı Jekyll zoraki bir gülümsemeyle.', 'notes': 'forced smile: zoraki gülümseme.'}, {'id': 53, 'text': '"I have learned things concerning young Hyde that would horrify any decent gentleman," the lawyer pressed.', 'translation': '"Genç Hyde hakkında her dürüst beyefendiyi dehşete düşürecek şeyler öğrendim," diye ısrar etti avukat.', 'notes': 'decent gentleman: dürüst/namuslu beyefendi.'}, {'id': 54, 'text': 'Jekyll grew deathly pale, and his lips trembled as he set down his glass upon the mantelpiece.', 'translation': "Jekyll'ın rengi ölüm gibi soldu ve kadehini şömine rafına koyarken dudakları titredi.", 'notes': 'deathly pale: ölüm gibi solgun.'}, {'id': 55, 'text': '"I do not care to hear more; this is a painful matter that cannot be mended by talking," Jekyll insisted.', 'translation': '"Daha fazlasını duymak istemiyorum; bu konuşarak düzeltilemeyecek acı verici bir meseledir," diye ısrar etti Jekyll.', 'notes': 'cannot be mended: düzeltilemez.'}, {'id': 56, 'text': '"Jekyll, you know you can trust me; make a clean breast of it, and I will help you!" Utterson pleaded.', 'translation': '"Jekyll, bana güvenebileceğini biliyorsun; içini dök bana, sana yardım edeceğim!" diye yalvardı Utterson.', 'notes': 'make a clean breast: içini dökmek, her şeyi itiraf etmek.'}, {'id': 57, 'text': '"You are a noble friend, Utterson, but my position is very strange—one that no one can fathom,"', 'translation': '"Sen asil bir dostsun Utterson fakat durumum çok garip—hiç kimsenin akıl erdiremeyeceği bir durum,"', 'notes': 'no one can fathom: kimsenin akıl erdiremeyeceği.'}, {'id': 58, 'text': '"I can assure you of one thing: the moment I choose, I can be rid of Mr. Hyde forever."', 'translation': '"Sana bir şeyin güvencesini verebilirim: Dilediğim an Bay Hyde\'dan sonsuza dek kurtulabilirim."', 'notes': "rid of Mr. Hyde: Bay Hyde'dan kurtulmak."}, {'id': 59, 'text': '"I only ask that if I am ever taken away, you will promise to protect him and secure his rights."', 'translation': '"Sadece, eğer başıma bir şey gelirse onu koruyacağına ve haklarını güvence altına alacağına söz vermeni istiyorum."', 'notes': 'secure his rights: haklarını güvenceye almak.'}, {'id': 60, 'text': 'With a heavy sigh, Utterson reluctantly gave his professional pledge, and the subject was dropped.', 'translation': 'Ağır bir iç çekişle Utterson gönülsüzce mesleki sözünü verdi ve konu kapandı.', 'notes': 'subject was dropped: konu kapandı.'}]}, {'page_no': 4, 'title': 'The Carew Murder Case', 'tr_title': 'Carew Cinayeti Vakası', 'vocab_focus': [('auditorium', 'dinleyici salonu'), ('maid', 'hizmetçi kız'), ('cane', 'baston'), ('splinter', 'kıymık, parçalanmak'), ('audible', 'işitilebilir, duyulabilir'), ('brutal', 'acımasız, vahşi'), ('fury', 'öfke, hiddet'), ('shattered', 'paramparça olmuş')], 'sentences': [{'id': 61, 'text': 'Nearly a year later, in the month of October, London was startled by a crime of singular ferocity.', 'translation': 'Neredeyse bir yıl sonra, ekim ayında Londra benzeri görülmemiş bir vahşetteki bir cinayetle sarsıldı.', 'notes': 'singular ferocity: benzeri görülmemiş vahşet.'}, {'id': 62, 'text': 'The details were particularly shocking because the victim was an eminent and beloved member of society.', 'translation': 'Ayrıntılar bilhassa şoke ediciydi çünkü kurban toplumun seçkin ve çok sevilen bir üyesiydi.', 'notes': 'eminent member: seçkin üye.'}, {'id': 63, 'text': "A romantic maidservant was sitting by her bedroom window overlooking the quiet river at eleven o'clock at night.", 'translation': 'Romantik bir hizmetçi kız gece saat on birde sessiz nehre bakan yatak odası penceresinin kenarında oturuyordu.', 'notes': 'maidservant: hizmetçi kız.'}, {'id': 64, 'text': 'The full moon shone brilliantly, bathing the empty lane in peaceful, silvery radiance.', 'translation': 'Dolunay ışıl ışıl parlıyor, ıssız sokağı huzurlu, gümüşsü bir ışıltıyla yıkıyordu.', 'notes': 'silvery radiance: gümüşsü ışıltı.'}, {'id': 65, 'text': 'She observed an aged, beautiful gentleman with silver hair advancing politely along the pathway.', 'translation': 'Gümüş saçlı, yaşlı ve güzel çehreli bir beyefendinin patika boyunca nezaketle ilerlediğini gördü.', 'notes': 'advancing politely: nezaketle ilerleyen.'}, {'id': 66, 'text': 'Presently, he was met by another gentleman, a very small man whom she recognized as Mr. Edward Hyde.', 'translation': 'Az sonra karşısına, kızın Bay Edward Hyde olarak tanıdığı çok ufak tefek başka bir adam çıktı.', 'notes': 'recognized as: olarak tanıdı.'}, {'id': 67, 'text': 'Hyde had once visited her master and had left an extraordinarily repulsive impression upon her mind.', 'translation': 'Hyde bir keresinde efendisini ziyaret etmiş ve kızın zihninde olağanüstü derecede itici bir izlenim bırakmıştı.', 'notes': 'repulsive impression: itici izlenim.'}, {'id': 68, 'text': 'The elderly gentleman bowed courteously and seemed to ask for directions with an old-world politeness.', 'translation': 'Yaşlı beyefendi nezaketle eğildi ve eski usul bir kibarlıkla yol tarifini sorar gibi göründü.', 'notes': 'old-world politeness: eski usul kibarlık.'}, {'id': 69, 'text': 'Suddenly, Mr. Hyde burst into a flame of inexplicable, ape-like fury!', 'translation': 'Ansızın Bay Hyde açıklanamaz, maymunsu bir öfke alevine kapıldı!', 'notes': 'ape-like fury: maymunsu öfke.'}, {'id': 70, 'text': 'He stamped his feet, brandished his heavy cane, and snarled like an escaped wild beast.', 'translation': 'Ayaklarını yere vurdu, ağır bastonunu havada salladı ve kaçmış vahşi bir hayvan gibi hırladı.', 'notes': 'brandished his cane: bastonunu savurdu.'}, {'id': 71, 'text': 'The innocent gentleman stepped back in utter astonishment, raising his hands in defensive confusion.', 'translation': 'Masum beyefendi büyük bir şaşkınlıkla geriledi; savunmacı bir kafa karışıklığıyla ellerini kaldırdı.', 'notes': 'defensive confusion: savunmacı şaşkınlık.'}, {'id': 72, 'text': 'Hyde leaped forward and struck the gentleman across the head with the heavy cane, knocking him to the earth.', 'translation': 'Hyde öne atıldı ve ağır bastonla beyefendinin kafasına vurarak onu yere serdi.', 'notes': 'knocking him to earth: onu yere sererek.'}, {'id': 73, 'text': 'With animal savagery, Hyde jumped upon his victim and trampled him beneath his heavy boots.', 'translation': 'Hayvanca bir vahşilikle Hyde kurbanının üzerine atladı ve onu ağır çizmelerinin altında çiğnedi.', 'notes': 'animal savagery: hayvanca vahşilik.'}, {'id': 74, 'text': "A sickening storm of blows rained down upon the body, audible even inside the maid's high chamber.", 'translation': 'Hizmetçinin yüksekteki odasından bile işitilebilen mide bulandırıcı bir darbe fırtınası cesedin üzerine yağdı.', 'notes': 'storm of blows: darbe yağmuru/fırtınası.'}, {'id': 75, 'text': "Bones could be heard audibly shattering beneath the relentless fury of the madman's assault.", 'translation': 'Delinin acımasız saldırısı altında kemiklerin duyulabilir şekilde kırıldığı işitiliyordu.', 'notes': 'audibly shattering: seslice parçalanan.'}, {'id': 76, 'text': 'The heavy wooden cane snapped in half beneath the ferocious violence of the blows.', 'translation': 'Ağır tahta baston darbelerin vahşi şiddeti altında ortadan ikiye kırıldı.', 'notes': 'snapped in half: ortadan ikiye kırıldı.'}, {'id': 77, 'text': 'Horrified by the sight and sound of the murder, the servant girl fainted upon the floor.', 'translation': 'Cinayetin görüntüsü ve sesinden dehşete düşen hizmetçi kız yere yığılarak bayıldı.', 'notes': 'fainted upon floor: yere bayıldı.'}, {'id': 78, 'text': 'When she regained consciousness hours later and called the police, the murderer was long gone.', 'translation': 'Saatler sonra kendine gelip polisi aradığında katil çoktan sırra kadem basmıştı.', 'notes': 'regained consciousness: kendine geldi, ayıltı.'}, {'id': 79, 'text': 'The victim lay battered and lifeless upon the pavement, his gold watch and purse untouched beside him.', 'translation': 'Kurban kaldırımda hırpalanmış ve cansız yatıyordu; altın saati ve cüzdanı yanı başında el değmemiş duruyordu.', 'notes': 'battered and lifeless: hırpalanmış ve cansız.'}, {'id': 80, 'text': 'In his coat pocket, officers found a sealed letter addressed to Mr. Gabriel John Utterson.', 'translation': "Ceketinin cebinde polis memurları Bay Gabriel John Utterson'a hitaben mühürlü bir mektup buldular.", 'notes': 'sealed letter: mühürlü mektup.'}]}, {'page_no': 5, 'title': 'Incident of the Letter and the Soho Den', 'tr_title': "Soho'daki İn ve Bastonun Sırrı", 'vocab_focus': [('inquest', 'adli soruşturma, tahkikat'), ('parliament', 'parlamento'), ('splintered', 'parçalanmış, kırılmış'), ('heirloom', 'aile yadigarı'), ('fog', 'sis'), ('dismal', 'kasvetli, iç karartıcı'), ('slum', 'gecekondu mahallesi, varoş'), ('chequebook', 'çek defteri')], 'sentences': [{'id': 81, 'text': 'The police summoned Utterson to the station the following morning to inspect the body and the letter.', 'translation': "Polis cesedi ve mektubu incelemesi için ertesi sabah Utterson'ı karakola çağırdı.", 'notes': 'summoned to the station: karakola çağırdı.'}, {'id': 82, 'text': 'Utterson looked upon the battered remains and recognized the deceased with profound shock and sorrow.', 'translation': 'Utterson hırpalanmış kalıntılara baktı ve merhumu büyük bir şok ve kederle tanıdı.', 'notes': 'battered remains: hırpalanmış kalıntılar.'}, {'id': 83, 'text': '"It is Sir Danvers Carew, a distinguished Member of Parliament and my client!" Utterson declared gravely.', 'translation': '"Bu Parlamentonun seçkin bir üyesi ve müvekkilim olan Sör Danvers Carew!" diye ciddiyetle bildirdi Utterson.', 'notes': 'Member of Parliament: Parlamento Üyesi, milletvekili.'}, {'id': 84, 'text': 'Inspector Newcomen of Scotland Yard showed Utterson the broken half of the heavy walking cane found at the scene.', 'translation': "Scotland Yard'dan Müfettiş Newcomen olay yerinde bulunan ağır yürüyüş bastonunun kırık yarısını Utterson'a gösterdi.", 'notes': 'walking cane: yürüyüş bastonu.'}, {'id': 85, 'text': 'Utterson recognized the cane with a sickening jolt: it was a rare wooden stick he had presented to Henry Jekyll years ago!', 'translation': "Utterson bastonu midesini bulandıran bir sarsıntıyla tanıdı: Yıllar önce bizzat Henry Jekyll'a hediye ettiği nadir bir tahta bastondu bu!", 'notes': 'sickening jolt: sarsıcı şok.'}, {'id': 86, 'text': '"If you will come with me in a carriage, Inspector, I can take you to the murderer\'s lodgings," Utterson offered.', 'translation': '"Eğer benimle bir faytona binerseniz Müfettiş, sizi katilin kaldığı eve götürebilirim," diye teklif etti Utterson.', 'notes': "murderer's lodgings: katilin kaldığı yer."}, {'id': 87, 'text': 'They drove through a dense chocolate-colored fog that had rolled over the dreary streets of Soho.', 'translation': "Soho'nun kasvetli sokaklarını kaplayan çikolata rengi yoğun bir sisin içinden arabayla geçtiler.", 'notes': 'chocolate-colored fog: çikolata rengi sis.'}, {'id': 88, 'text': 'Soho was a dismal district of squalid gin-palaces, ragged children, and foreign immigrants.', 'translation': 'Soho sefil meyhanelerin, üstü başı yırtık çocukların ve yabancı göçmenlerin yaşadığı kasvetli bir semtti.', 'notes': 'dismal district: kasvetli semt.'}, {'id': 89, 'text': "They halted before Hyde's residence, where an evil-faced old woman with silvery hair answered the door.", 'translation': "Hyde'ın kaldığı evin önünde durdular; gümüş saçlı ve kötü yüzlü yaşlı bir kadın kapıyı açtı.", 'notes': 'evil-faced: kötü yüzlü.'}, {'id': 90, 'text': 'She admitted that Mr. Hyde lodged there, but reported that he had arrived very late and left an hour before.', 'translation': "Bay Hyde'ın orada kaldığını kabul etti ancak gece çok geç geldiğini ve bir saat önce ayrıldığını bildirdi.", 'notes': 'lodged there: orada kalıyordu.'}, {'id': 91, 'text': '"We wish to inspect his rooms; this is Inspector Newcomen of Scotland Yard," Utterson announced firmly.', 'translation': '"Odalarını aramak istiyoruz; bu bey Scotland Yard\'dan Müfettiş Newcomen," diye kararlılıkla duyurdu Utterson.', 'notes': 'announced firmly: kararlılıkla duyurdu.'}, {'id': 92, 'text': "Hyde's rooms presented an astonishing contrast to the squalor of the surrounding neighborhood.", 'translation': "Hyde'ın odaları çevredeki mahallenin sefaletiyle şaşırtıcı bir tezat oluşturuyordu.", 'notes': 'astonishing contrast: şaşırtıcı tezat.'}, {'id': 93, 'text': 'The apartment was furnished with luxurious carpets, costly mahogany furniture, fine wine, and silver tableware.', 'translation': 'Daire lüks halılar, pahalı maun mobilyalar, kaliteli şaraplar ve gümüş sofra takımlarıyla döşenmişti.', 'notes': 'luxurious carpets: lüks halılar.'}, {'id': 94, 'text': 'However, the rooms bore evidence of a hurried and panicked flight.', 'translation': 'Fakat odalar aceleli ve panik dolu bir kaçışın izlerini taşıyordu.', 'notes': 'panicked flight: panik dolu kaçış.'}, {'id': 95, 'text': 'Clothes were strewn across the floor with their pockets turned inside out, and drawers stood open.', 'translation': 'Giysiler cepleri dışarı çıkarılmış halde yere saçılmıştı ve çekmeceler ardına kadar açıktı.', 'notes': 'turned inside out: tersyüz edilmiş.'}, {'id': 96, 'text': 'In the cold fireplace lay a heap of grey ashes from newly burned papers and documents.', 'translation': 'Soğuk şöminede yeni yakılmış evrak ve belgelerden geriye kalan gri bir kül yığını duruyordu.', 'notes': 'heap of ashes: kül yığını.'}, {'id': 97, 'text': 'From the embers, the inspector retrieved the scorched butt of a green chequebook.', 'translation': 'Müfettiş küllerin arasından yeşil bir çek defterinin yanmış koçanını çıkardı.', 'notes': 'scorched butt: yanmış dip/koçan.'}, {'id': 98, 'text': "Behind the door, Utterson discovered the other half of the broken cane, confirming Hyde's guilt beyond doubt.", 'translation': "Kapının arkasında Utterson kırık bastonun diğer yarısını buldu ve Hyde'ın suçunu şüpheye yer bırakmayacak şekilde doğruladı.", 'notes': 'confirming guilt: suçu doğrulayan.'}, {'id': 99, 'text': "A visit to the bank revealed that thousands of pounds lay in Hyde's account, but he never returned to claim it.", 'translation': "Bankaya yapılan bir ziyaret Hyde'ın hesabında binlerce pound yattığını gösterdi fakat parayı çekmek için hiç dönmedi.", 'notes': 'claim money: parayı talep etmek/almak.'}, {'id': 100, 'text': 'Edward Hyde had vanished into the foggy labyrinth of the metropolis, leaving no photograph or known relatives behind.', 'translation': 'Edward Hyde arkasında ne bir fotoğraf ne de bilinen bir akraba bırakarak büyük kentin sisli labirentinde kaybolmuştu.', 'notes': 'foggy labyrinth: sisli labirent.'}]}, {'page_no': 6, 'title': 'The Calligraphic Mystery of Mr. Guest', 'tr_title': 'Mektubun Sırrı ve Kaligrafi İncelemesi', 'vocab_focus': [('laboratory', 'laboratuvar'), ('dissecting', 'kadavra kesme, anatomi'), ('calligraphy', 'kaligrafi, güzel yazı'), ('handwriting', 'el yazısı'), ('autograph', 'el yazısı imza'), ('identical', 'tıpatıp aynı'), ('slope', 'eğim, eğilmek'), ('forgery', 'sahtecilik, taklit')], 'sentences': [{'id': 101, 'text': "Late that afternoon, Utterson went straight to Dr. Jekyll's house and was admitted to the rear laboratory.", 'translation': "O öğleden sonranın geç saatlerinde Utterson doğruca Doktor Jekyll'ın evine gitti ve arka laboratuvara alındı.", 'notes': 'rear laboratory: arka laboratuvar.'}, {'id': 102, 'text': 'The laboratory was a dingy, windowless building that had once served as a surgical dissection theatre.', 'translation': 'Laboratuvar bir zamanlar cerrahi anatomi salonu olarak hizmet vermiş kasvetli, penceresiz bir binaydı.', 'notes': 'dingy building: kasvetli bina.'}, {'id': 103, 'text': 'Dr. Jekyll sat beside the hearth in his private cabinet above the laboratory, looking deathly sick.', 'translation': 'Doktor Jekyll laboratuvarın üzerindeki özel çalışma odasında şöminenin yanında ölümcül bir hasta gibi oturuyordu.', 'notes': 'deathly sick: ölümcül hasta.'}, {'id': 104, 'text': 'He held out a cold hand and welcomed his friend in a voice changed almost beyond recognition.', 'translation': 'Soğuk elini uzattı ve neredeyse tanınmayacak kadar değişmiş bir sesle dostunu karşıladı.', 'notes': 'beyond recognition: tanınmayacak derecede.'}, {'id': 105, 'text': '"Have you heard the news, Henry?" Utterson asked; "Carew was murdered, and your cane was found at the scene!"', 'translation': '"Haberi duydun mu Henry?" diye sordu Utterson; "Carew katledildi ve senin bastonun olay yerinde bulundu!"', 'notes': 'found at the scene: olay yerinde bulundu.'}, {'id': 106, 'text': '"Carew!" cried Jekyll, burying his face in his hands; "What a terrible catastrophe!"', 'translation': '"Carew mu!" diye haykırdı Jekyll yüzünü ellerine gömerek; "Ne korkunç bir felaket!"', 'notes': 'terrible catastrophe: korkunç felaket.'}, {'id': 107, 'text': '"I swear to God," Jekyll cried with trembling emotion, "I swear I will never set eyes upon Edward Hyde again!"', 'translation': '"Tanrı üzerine yemin ederim ki," diye haykırdı Jekyll titreyen bir duyguyla, "Edward Hyde\'ı bir daha asla görmeyeceğim!"', 'notes': 'never set eyes upon: bir daha asla görmemek.'}, {'id': 108, 'text': '"I bind my honor that I am done with him in this world; it is all at an end!"', 'translation': '"Bu dünyada onunla işimin bittiğine şerefim üzerine ant içerim; her şey bitti artık!"', 'notes': 'bind my honor: şerefim üzerine ant içerim.'}, {'id': 109, 'text': 'Jekyll handed Utterson an unfolded letter written in an odd, upright hand and signed "Edward Hyde."', 'translation': 'Jekyll Utterson\'a tuhaf, dik bir el yazısıyla yazılmış ve "Edward Hyde" imzalı açılmış bir mektup uzattı.', 'notes': 'upright hand: dik el yazısı.'}, {'id': 110, 'text': 'The letter stated that Jekyll need not worry, for Hyde possessed a certain means of escape and would never return.', 'translation': "Mektup Jekyll'ın endişelenmemesini zira Hyde'ın kesin bir kaçış yoluna sahip olduğunu ve asla dönmeyeceğini belirtiyordu.", 'notes': 'certain means of escape: kesin kaçış yolu.'}, {'id': 111, 'text': 'Utterson took the letter home and called his head clerk, Mr. Guest, into his private office.', 'translation': "Utterson mektubu eve götürdü ve başkatibi Bay Guest'i özel ofisine çağırdı.", 'notes': 'head clerk: başkatip.'}, {'id': 112, 'text': 'Guest was an expert in handwriting and calligraphy, often consulted on legal documents.', 'translation': 'Guest el yazısı ve kaligrafi konusunda bir uzmandı ve yasal belgeler için kendisine sık sık danışılırdı.', 'notes': 'expert in calligraphy: kaligrafi uzmanı.'}, {'id': 113, 'text': 'Just then, a servant brought in an invitation dinner note handwritten by Dr. Henry Jekyll himself.', 'translation': "Tam o sırada bir uşak bizzat Doktor Henry Jekyll'ın kendi el yazısıyla yazdığı bir akşam yemeği davetiyesini içeri getirdi.", 'notes': 'invitation dinner note: akşam yemeği davetiyesi.'}, {'id': 114, 'text': 'Guest laid the two letters side by side upon the desk and studied them with intense fascination.', 'translation': 'Guest iki mektubu masanın üzerine yan yana koydu ve onları yoğun bir merakla inceledi.', 'notes': 'intense fascination: yoğun merak/büyülenme.'}, {'id': 115, 'text': '"The two hands are identical in almost every singular character," Guest announced quietly.', 'translation': '"İki el yazısı neredeyse her bir karakterinde tıpatıp aynı," dedi Guest sessizce.', 'notes': 'identical in character: karakter olarak tıpatıp aynı.'}, {'id': 116, 'text': '"They differ only in their slope: one leans forward, while the other stands strictly upright."', 'translation': '"Yalnızca eğimlerinde farklılık gösteriyorlar: Biri öne doğru eğik, diğeri ise tamamen dik duruyor."', 'notes': 'differ in slope: eğimde farklılaşmak.'}, {'id': 117, 'text': 'Utterson\'s blood ran cold: "Do you mean to say that Henry Jekyll forged a letter for a murderer?"', 'translation': 'Utterson\'ın kanı dondu: "Henry Jekyll\'ın bir katil için sahte mektup yazdığını mı söylemek istiyorsun?"', 'notes': 'blood ran cold: kanı dondu.'}, {'id': 118, 'text': '"It would appear so, sir," Guest replied with discreet gravity.', 'translation': '"Öyle görünüyor efendim," diye yanıtladı Guest ketum bir ciddiyetle.', 'notes': 'discreet gravity: ketum/ölçülü ciddiyet.'}, {'id': 119, 'text': 'Utterson locked the two letters in his iron safe, determined never to speak of the discovery to another living soul.', 'translation': 'Utterson bu keşiften yaşayan başka hiçbir ruha söz etmemeye kararlı olarak iki mektubu demir kasasına kilitledi.', 'notes': 'living soul: yaşayan can/ruh.'}, {'id': 120, 'text': 'He could not comprehend why his honorable friend would risk the gallows to shield a vicious assassin.', 'translation': 'Saygın dostunun vahşi bir suikastçıyı korumak için neden darağacını göze aldığını bir türlü anlayamıyordu.', 'notes': 'risk the gallows: darağacını/idamı göze almak.'}]}, {'page_no': 7, 'title': 'Remarkable Incident of Dr. Lanyon', 'tr_title': "Doktor Lanyon'ın Sıradışı Olayı", 'vocab_focus': [('philanthropy', 'hayırseverlik'), ('seclusion', 'inziva, el etek çekme'), ('emaciated', 'bir deri bir kemik kalmış'), ('decay', 'çöküş, yıpranma'), ('unrecoverable', 'telafi edilemez, kurtarılamaz'), ('condemn', 'mahkûm etmek, kınamak'), ('shivering', 'titreme'), ('fatal', 'ölümcül')], 'sentences': [{'id': 121, 'text': 'Time ran on; thousands of pounds were offered in reward for Hyde, but he had vanished as if he had never existed.', 'translation': 'Zaman aktı geçti; Hyde için binlerce pound ödül kondu fakat sanki hiç var olmamış gibi sırra kadem basmıştı.', 'notes': 'offered in reward: ödül olarak kondu.'}, {'id': 122, 'text': 'With the evil influence removed, a new and splendid era began for Dr. Henry Jekyll.', 'translation': 'Kötü etkinin ortadan kalkmasıyla Doktor Henry Jekyll için yepyeni ve muhteşem bir dönem başladı.', 'notes': 'splendid era: muhteşem dönem.'}, {'id': 123, 'text': 'He came out of his seclusion, renewed relations with his old friends, and devoted his wealth to extensive philanthropy.', 'translation': 'İnzivasından çıktı, eski dostlarıyla ilişkilerini tazeledi ve servetini kapsamlı hayır işlerine adadı.', 'notes': 'extensive philanthropy: kapsamlı hayırseverlik.'}, {'id': 124, 'text': 'His face looked open, bright, and cheerful, as if a dark demon had been lifted from his weary soul.', 'translation': 'Sanki yorgun ruhundan karanlık bir iblis kaldırılmış gibi yüzü açık, aydınlık ve neşeli görünüyordu.', 'notes': 'weary soul: yorgun ruh.'}, {'id': 125, 'text': 'For two peaceful months, Jekyll lived a virtuous and hospitable life in the sight of all London.', 'translation': "Huzur dolu iki ay boyunca Jekyll tüm Londra'nın gözü önünde erdemli ve konuksever bir hayat sürdü.", 'notes': 'virtuous life: erdemli yaşam.'}, {'id': 126, 'text': "On the eighth of January, Utterson dined at Jekyll's house with Dr. Lanyon, and all seemed joyous and harmonious.", 'translation': "Sekiz Ocak'ta Utterson Doktor Lanyon ile birlikte Jekyll'ın evinde akşam yemeği yedi ve her şey neşeli ve uyumlu görünüyordu.", 'notes': 'joyous and harmonious: neşeli ve ahenkli.'}, {'id': 127, 'text': 'Yet on the twelfth, and again on the fourteenth, Utterson called at the house and was refused admittance.', 'translation': 'Fakat ayın on ikisinde ve tekrar on dördünde Utterson eve uğradı ve içeri alınmadı.', 'notes': 'refused admittance: içeri kabul edilmedi.'}, {'id': 128, 'text': '"The doctor is confined to his room and sees no one," Poole informed the lawyer with an anxious frown.', 'translation': '"Doktor odasına kapandı ve kimseyi görmüyor," diye bildirdi Poole endişeli bir kaş çatışıyla avukata.', 'notes': 'confined to his room: odasına kapanmış.'}, {'id': 129, 'text': 'Troubled by this sudden withdrawal, Utterson walked over to Cavendish Square to consult Dr. Lanyon.', 'translation': "Bu ani geri çekilmeden rahatsız olan Utterson Doktor Lanyon'a danışmak için Cavendish Meydanı'na yürüdü.", 'notes': 'sudden withdrawal: ani geri çekilme.'}, {'id': 130, 'text': 'When Lanyon entered the drawing-room, Utterson was struck to the heart by the horrifying change in his friend.', 'translation': 'Lanyon salona girdiğinde Utterson dostundaki korkunç değişim karşısında yüreğinden vurulmuşa döndü.', 'notes': 'struck to the heart: yüreğinden vurulmuşa döndü.'}, {'id': 131, 'text': 'Lanyon had his death-warrant written legibly upon his emaciated, pale face.', 'translation': "Lanyon'ın bir deri bir kemik kalmış solgun yüzünde ölüm fermanı açıkça okunuyordu.", 'notes': 'death-warrant: ölüm fermanı.'}, {'id': 132, 'text': 'His rosy flesh had fallen away, he had grown visibly older, and his eyes burned with deep-seated terror.', 'translation': 'Al yanakları çökmüş, gözle görülür şekilde yaşlanmıştı ve gözleri köklü bir dehşetle yanıyordu.', 'notes': 'deep-seated terror: köklü/derin dehşet.'}, {'id': 133, 'text': '"I have had a shock," Lanyon whispered in a trembling voice, "and I shall never recover."', 'translation': '"Bir şok geçirdim," diye fısıldadı Lanyon titreyen bir sesle, "ve asla toparlanamayacağım."', 'notes': 'never recover: asla toparlanamamak.'}, {'id': 134, 'text': '"It is a question of weeks; life has become unendurable, and I look forward to death."', 'translation': '"Bu birkaç haftalık bir mesele; hayat katlanılmaz hale geldi ve ölümü sabırsızlıkla bekliyorum."', 'notes': 'look forward to death: ölümü beklemek.'}, {'id': 135, 'text': "When Utterson mentioned Jekyll's name, Lanyon's face flushed with violent indignation.", 'translation': "Utterson Jekyll'ın adını andığında Lanyon'ın yüzü şiddetli bir öfkeyle kızardı.", 'notes': 'violent indignation: şiddetli öfke/hiddet.'}, {'id': 136, 'text': '"Hold your tongue!" Lanyon cried out; "I will hear no more of Henry Jekyll!"', 'translation': '"Dilini tut!" diye haykırdı Lanyon; "Henry Jekyll hakkında tek bir kelime daha duymak istemiyorum!"', 'notes': 'hold your tongue: dilini tut, sus.'}, {'id': 137, 'text': '"I consider that man dead to me forever, and I forbid you to speak his name in my presence!"', 'translation': '"O adamı benim için sonsuza dek ölmüş sayıyorum ve huzurumda onun adını anmanı yasaklıyorum!"', 'notes': 'dead to me forever: benim için ebediyen ölmüş.'}, {'id': 138, 'text': 'Utterson went home and wrote a letter to Jekyll, questioning this tragic rupture and asking why he kept secluded.', 'translation': "Utterson eve gidip Jekyll'a bir mektup yazarak bu trajik kopuşu sorguladı ve neden inzivaya çekildiğini sordu.", 'notes': 'tragic rupture: trajik kopuş/ayrılık.'}, {'id': 139, 'text': 'Jekyll replied in a dark, despairing letter: "You must respect my silence; I am under a dark penalty that I cannot name."', 'translation': 'Jekyll karanlık, umutsuz bir mektupla yanıt verdi: "Sessizliğime saygı duymalısın; adını koyamadığım kara bir ceza altındayım."', 'notes': 'dark penalty: kara/ağır ceza.'}, {'id': 140, 'text': 'Less than three weeks later, Dr. Hastie Lanyon took to his bed, closed his weary eyes, and died.', 'translation': 'Üç haftadan az bir süre sonra Doktor Hastie Lanyon yatağa düştü, yorgun gözlerini kapadı ve öldü.', 'notes': 'took to his bed: yatağa düştü.'}]}, {'page_no': 8, 'title': 'The Sealed Packet and the Solitary Prisoner', 'tr_title': 'Mühürlü Paket ve Yalnız Mahkûm', 'vocab_focus': [('packet', 'paket, zarf'), ('confidential', 'gizli, mahrem'), ('disappearance', 'kayboluş'), ('curiosity', 'merak'), ('honor', 'şeref, onur'), ('seclusion', 'inziva, tecrit'), ('drawer', 'çekmece'), ('disconsolate', 'kederli, tesellisiz')], 'sentences': [{'id': 141, 'text': "On the night after Dr. Lanyon's solemn funeral, Utterson sat alone in his gloomy study.", 'translation': "Doktor Lanyon'ın hüzünlü cenazesinin ertesi gecesinde Utterson kasvetli çalışma odasında tek başına oturdu.", 'notes': 'solemn funeral: hüzünlü cenaze töreni.'}, {'id': 142, 'text': "Upon his desk lay a thick envelope sealed with wax and addressed in the dead doctor's handwriting.", 'translation': 'Masasının üzerinde balmumuyla mühürlenmiş ve merhum doktorun el yazısıyla adreslenmiş kalın bir zarf duruyordu.', 'notes': 'sealed with wax: balmumuyla mühürlü.'}, {'id': 143, 'text': 'The inscription read: "PRIVATE: for the hands of G. J. Utterson alone, and in case of his death, to be destroyed unread."', 'translation': 'Üzerindeki yazıda şöyle yazıyordu: "ÖZEL: Yalnızca G. J. Utterson\'ın ellerine verilecek; ölümü halinde okunmadan imha edilecektir."', 'notes': 'destroyed unread: okunmadan imha edilmek.'}, {'id': 144, 'text': 'With trembling fingers, the lawyer broke the outer seal, only to find another sealed inner envelope.', 'translation': 'Titreyen parmaklarla avukat dış mührü açtı; ancak içeride mühürlü bir başka iç zarf buldu.', 'notes': 'inner envelope: iç zarf.'}, {'id': 145, 'text': 'Upon the inner envelope was written: "not to be opened till the death or disappearance of Dr. Henry Jekyll."', 'translation': 'İç zarfın üzerinde şöyle yazıyordu: "Doktor Henry Jekyll\'ın ölümüne veya ortadan kaybolmasına kadar açılmayacaktır."', 'notes': 'till death or disappearance: ölüme veya kayboluşa kadar.'}, {'id': 146, 'text': 'Utterson could scarcely believe his eyes: here again was that ominous phrase: "or disappearance"!', 'translation': 'Utterson gözlerine neredeyse inanamadı: İşte yine o uğursuz ifade karşısındaydı: "veya ortadan kaybolmasına"!', 'notes': 'ominous phrase: uğursuz ifade.'}, {'id': 147, 'text': 'It was the identical condition stated in the bizarre will he had so long despised.', 'translation': 'Uzun süredir nefret ettiği o tuhaf vasiyetnamede belirtilen şartın tıpatıp aynısıydı bu.', 'notes': 'identical condition: tıpatıp aynı şart.'}, {'id': 148, 'text': 'Utterson was sorely tempted to tear open the envelope and uncover the dark mystery at once.', 'translation': 'Utterson zarfı derhal yırtıp açmak ve o karanlık gizemi bir anda ortaya çıkarmak için büyük bir ayartılma hissetti.', 'notes': 'sorely tempted: son derece ayartılmış/istekli.'}, {'id': 149, 'text': "Yet his legal honor and devotion to his dead friend's wishes prevailed over his curiosity.", 'translation': 'Fakat mesleki onuru ve ölmüş dostunun dileklerine olan sadakati merakına üstün geldi.', 'notes': 'prevailed over curiosity: meraka galip geldi.'}, {'id': 150, 'text': 'He placed the mysterious packet back into the innermost corner of his private iron safe.', 'translation': 'Esrarengiz paketi özel demir kasasının en dip köşesine geri yerleştirdi.', 'notes': 'innermost corner: en dip köşe.'}, {'id': 151, 'text': "Over the following weeks, Utterson called repeatedly at Jekyll's house in the square.", 'translation': "Takip eden haftalarda Utterson meydandaki Jekyll'ın evine defalarca uğradı.", 'notes': 'called repeatedly: defalarca uğradı/ziyaret etti.'}, {'id': 152, 'text': 'Each time, Poole stood upon the threshold, shaking his head with sorrowful apology.', 'translation': 'Her seferinde Poole kederli bir özürle başını iki yana sallayarak kapı eşiğinde durdu.', 'notes': 'sorrowful apology: kederli özür.'}, {'id': 153, 'text': '"The doctor remains locked in the cabinet above the laboratory, sir; he refuses all company."', 'translation': '"Doktor laboratuvarın üzerindeki çalışma odasında kilitli kalmaya devam ediyor efendim; kimseyle görüşmeyi kabul etmiyor."', 'notes': 'refuses all company: tüm ziyaretçileri reddediyor.'}, {'id': 154, 'text': "Gradually, Utterson's visits grew less frequent as he realized his presence only caused distress.", 'translation': "Varlığının yalnızca sıkıntıya yol açtığını fark eden Utterson'ın ziyaretleri giderek seyrekleşti.", 'notes': 'grew less frequent: seyrekleşti.'}, {'id': 155, 'text': 'It seemed that Dr. Jekyll had buried himself alive in his lonely chemical workshop.', 'translation': 'Görünüşe göre Doktor Jekyll yalnız kimya atölyesinde kendisini diri diri mezara gömmüştü.', 'notes': 'buried himself alive: kendini diri diri gömmüştü.'}, {'id': 156, 'text': 'The great house was silent as a tomb, its former hospitality extinguished entirely.', 'translation': 'Büyük ev bir mezar kadar sessizdi; eski konukseverliği tamamen sönüp gitmişti.', 'notes': 'silent as a tomb: mezar gibi sessiz.'}, {'id': 157, 'text': 'Only the chimney of the laboratory smoked occasionally against the grey London sky.', 'translation': 'Gri Londra gökyüzüne karşı yalnızca laboratuvarın bacası ara sıra tütüyordu.', 'notes': 'smoked occasionally: ara sıra tütüyordu.'}, {'id': 158, 'text': "Utterson feared that his friend's sanity was slipping away into madness.", 'translation': 'Utterson dostunun akıl sağlığının deliliğe doğru kayıp gitmesinden korkuyordu.', 'notes': 'sanity slipping away: akıl sağlığının yitip gitmesi.'}, {'id': 159, 'text': 'He wondered whether Edward Hyde was secretly haunting the dissecting rooms once again.', 'translation': "Edward Hyde'ın gizlice bir kez daha teşrih odalarını mesken tutup tutmadığını merak ediyordu.", 'notes': 'secretly haunting: gizlice mesken tutan.'}, {'id': 160, 'text': "Yet the terrifying reality of Jekyll's imprisonment was far beyond anything the lawyer could imagine.", 'translation': "Fakat Jekyll'ın mahkûmiyetinin o korkunç gerçeği, avukatın hayal edebileceği her şeyin çok ötesindeydi.", 'notes': 'far beyond imagination: hayal gücünün çok ötesinde.'}]}, {'page_no': 9, 'title': 'Incident at the Window', 'tr_title': 'Penceredeki Olay', 'vocab_focus': [('courtyard', 'avlu'), ('disconsolate', 'kederli, tesellisiz'), ('imprisonment', 'hapis, tutsaklık'), ('transfiguration', 'biçim değiştirme, başkalaşım'), ('abject', 'aşağılık, perişan'), ('terror', 'dehşet'), ('slam', 'çarpmak'), ('speechless', 'dili tutulmuş, nutku tutulmuş')], 'sentences': [{'id': 161, 'text': 'It chanced on Sunday, when Mr. Utterson was on his usual walk with Mr. Enfield, that their way lay once again through the byway.', 'translation': 'Bir pazar günü Bay Utterson Bay Enfield ile mutat yürüyüşündeyken yolları bir kez daha o ara sokaktan geçti.', 'notes': 'usual walk: mutat/alışıldık yürüyüş.'}, {'id': 162, 'text': 'They stepped into the narrow courtyard behind the laboratory building and looked up at the three tall windows.', 'translation': 'Laboratuvar binasının arkasındaki dar avluya adım attılar ve üç yüksek pencereye doğru yukarı baktılar.', 'notes': 'narrow courtyard: dar avlu.'}, {'id': 163, 'text': 'The middle window was halfway open, and sitting beside it, taking the air, was Dr. Henry Jekyll himself.', 'translation': "Ortadaki pencere yarıya kadar açıktı ve kenarında oturup hava alan kişi bizzat Doktor Henry Jekyll'ın kendisiydi.", 'notes': 'taking the air: hava alan.'}, {'id': 164, 'text': 'He looked infinitely sad and pale, resembling some disconsolate prisoner trapped within an impenetrable dungeon.', 'translation': 'Aşılmaz bir zindana tıkılmış tesellisiz bir mahkûmu andıran son derece kederli ve solgun bir hali vardı.', 'notes': 'disconsolate prisoner: tesellisiz mahkûm.'}, {'id': 165, 'text': '"What, Jekyll!" Utterson called up cheerfully; "I trust you are feeling better today!"', 'translation': '"Ne haber Jekyll!" diye neşeyle seslendi Utterson; "Umarım bugün kendini daha iyi hissediyorsundur!"', 'notes': 'called up cheerfully: neşeyle seslendi.'}, {'id': 166, 'text': '"I am very low, Utterson," the doctor replied feebly, "very low indeed; it will not last long, thank God."', 'translation': '"Çok düşkünüm Utterson," diye bitkin bir sesle yanıtladı doktor, "gerçekten çok düşkünüm; neyse ki çok uzun sürmeyecek Tanrı\'ya şükür."', 'notes': 'very low indeed: gerçekten çok düşkün/halsiz.'}, {'id': 167, 'text': '"You stay too much indoors; come, get your hat and take a quick turn with Enfield and me!" the lawyer urged.', 'translation': '"İçeride çok fazla kalıyorsun; hadi şapkanı al ve Enfield ile benimle hızlı bir tur atıver!" diye ısrar etti avukat.', 'notes': 'take a quick turn: hızlı bir tur atmak.'}, {'id': 168, 'text': '"You are very good, Utterson, and I should like to very much," Jekyll answered with a faint, sorrowful smile.', 'translation': '"Çok iyisin Utterson ve bunu gerçekten çok isterdim," diye yanıtladı Jekyll solgun, kederli bir tebessümle.', 'notes': 'sorrowful smile: kederli tebessüm.'}, {'id': 169, 'text': '"But it is quite impossible; I dare not; I am bearing a burden that permits no release."', 'translation': '"Fakat bu kesinlikle imkânsız; buna cesaret edemem; kurtuluşa izin vermeyen bir yük taşıyorum."', 'notes': 'permits no release: kurtuluşa izin vermeyen.'}, {'id': 170, 'text': '"Then we will stand here in the court and converse with you from where we are," Utterson offered kindly.', 'translation': '"O zaman biz burada avluda durup seninle bulunduğumuz yerden sohbet ederiz," diye nazikçe teklif etti Utterson.', 'notes': 'converse: sohbet etmek.'}, {'id': 171, 'text': '"That is just what I was about to venture to propose," the doctor smiled, nodding his head.', 'translation': '"Ben de tam bunu önermeye cüret etmek üzereydim," diye gülümsedi doktor başını sallayarak.', 'notes': 'venture to propose: önermeye cüret etmek.'}, {'id': 172, 'text': 'But the words were barely uttered when his smile was suddenly struck off his face with violent force.', 'translation': 'Fakat kelimeler ağzından henüz dökülmüştü ki tebessüm şiddetli bir güçle aniden yüzünden siliniverdi.', 'notes': 'struck off his face: yüzünden siliniverdi.'}, {'id': 173, 'text': 'An expression of such abject terror and despair succeeded that it froze the very blood of the two gentlemen below.', 'translation': 'Yerini öyle aşağılık bir dehşet ve umutsuzluk ifadesi aldı ki aşağıdaki iki beyefendinin damarlarındaki kanı dondurdu.', 'notes': 'abject terror: tarifsiz/aşağılık dehşet.'}, {'id': 174, 'text': 'They saw only a fleeting glimpse, for the window was instantly slammed shut with a resounding thud.', 'translation': 'Yalnızca anlık bir bakış yakalayabildiler zira pencere yankılanan bir gümlemeyle anında aşağıya çarpılarak kapatıldı.', 'notes': 'resounding thud: yankılanan gümleme.'}, {'id': 175, 'text': 'The glimpse had been sufficient; both men turned away and departed from the courtyard in absolute silence.', 'translation': 'O kısacık an yetmişti; iki adam da arkasını döndü ve mutlak bir sessizlik içinde avludan ayrıldı.', 'notes': 'glimpse had been sufficient: o bakış yetmişti.'}, {'id': 176, 'text': 'They traversed the adjoining thoroughfare without speaking a single word, their faces pale as ashes.', 'translation': 'Tek bir kelime bile etmeden bitişikteki ana caddeyi geçtiler; yüzleri kül gibi bembeyazdı.', 'notes': 'pale as ashes: kül gibi solgun.'}, {'id': 177, 'text': 'It was not until they turned into a crowded, bustling street that Utterson turned to his companion.', 'translation': "Utterson'ın yoldaşına dönmesi ancak kalabalık, hareketli bir caddeye girdiklerinde mümkün oldu.", 'notes': 'bustling street: hareketli cadde.'}, {'id': 178, 'text': '"God forgive us! God forgive us!" Mr. Utterson whispered in trembling, horrified tones.', 'translation': '"Tanrı bizi bağışlasın! Tanrı bizi affetsin!" diye fısıldadı Bay Utterson titreyen, dehşet dolu tonlarla.', 'notes': 'God forgive us: Tanrı bizi bağışlasın.'}, {'id': 179, 'text': 'Mr. Enfield only nodded his head in solemn, terrified agreement, unable to speak.', 'translation': 'Bay Enfield konuşamayacak durumda, yalnızca vakur ve dehşet dolu bir kabullenişle başını salladı.', 'notes': 'terrified agreement: dehşet dolu kabulleniş.'}, {'id': 180, 'text': 'The horrific mystery that had gripped Henry Jekyll had reached a catastrophic turning point.', 'translation': "Henry Jekyll'ı esir alan o korkunç gizem felaket getiren bir dönüm noktasına ulaşmıştı.", 'notes': 'catastrophic turning point: felaket dolu dönüm noktası.'}]}, {'page_no': 10, 'title': "The Last Night: Poole's Desperate Summons", 'tr_title': "Son Gece: Poole'un Çaresiz Çağrısı", 'vocab_focus': [('butler', 'baş uşak'), ('agitation', 'tedirginlik, telaş'), ('foul play', 'cinayet, hileli/karanlık oyun'), ('blustery', 'fırtınalı, rüzgarlı'), ('hearth', 'şömine'), ('paralyzed', 'felç olmuş, donakalmış'), ('hallway', 'koridor, hol'), ('dread', 'dehşet, derin korku')], 'sentences': [{'id': 181, 'text': 'Mr. Utterson was sitting by his fireside one wild, blustery evening in March when he received an unexpected visitor.', 'translation': 'Bay Utterson mart ayında fırtınalı, sert bir akşam şöminesi başında otururken beklenmedik bir ziyaretçi aldı.', 'notes': 'blustery evening: fırtınalı akşam.'}, {'id': 182, 'text': "Poole, Dr. Jekyll's elderly butler, was shown into the room, clutching his hat with trembling fingers.", 'translation': "Doktor Jekyll'ın yaşlı uşağı Poole titreyen parmaklarıyla şapkasını kavrayarak odaya alındı.", 'notes': 'elderly butler: yaşlı baş uşak.'}, {'id': 183, 'text': '"Bless my soul, Poole, what brings you here at this late hour?" Utterson asked, rising from his chair.', 'translation': '"Aman Tanrım Poole, bu geç saatte seni buraya getiren nedir?" diye sordu Utterson koltuğundan kalkarak.', 'notes': 'bless my soul: aman Tanrım.'}, {'id': 184, 'text': '"Mr. Utterson," the butler blurted out, unable to conceal his sheer panic, "there is something very wrong!"', 'translation': '"Bay Utterson," diye haykırdı uşak katıksız paniğini gizleyemeyerek, "Çok ters giden bir şeyler var!"', 'notes': 'sheer panic: katıksız panik.'}, {'id': 185, 'text': '"Take a seat, drink a glass of wine, and tell me plainly what is amiss," the lawyer said soothingly.', 'translation': '"Otur, bir kadeh şarap iç ve bana neyin ters gittiğini açıkça anlat," dedi avukat yatıştırıcı bir tavırla.', 'notes': 'what is amiss: neyin ters gittiği.'}, {'id': 186, 'text': '"You know the doctor\'s ways, sir, and how he shuts himself up in the cabinet," Poole began with a quivering lip.', 'translation': '"Efendimin hallerini ve çalışma odasına nasıl kapandığını bilirsiniz efendim," diye titreyen bir dudakla başladı Poole.', 'notes': 'quivering lip: titreyen dudak.'}, {'id': 187, 'text': '"Well, he\'s shut up again, and I don\'t like it, sir—I wish I may die if I like it!"', 'translation': '"İşte yine kapandı ve bu hiç hoşuma gitmiyor efendim—hoşuma gidiyorsa şuracıkta canım çıksın!"', 'notes': 'I wish I may die: canım çıksın ki.'}, {'id': 188, 'text': '"Be more explicit, Poole; what are you afraid of?" Utterson inquired with mounting concern.', 'translation': '"Daha açık konuş Poole; neden korkuyorsun?" diye sordu Utterson artan bir endişeyle.', 'notes': 'mounting concern: artan endişe.'}, {'id': 189, 'text': '"I\'ve been afraid for a week, sir," Poole whispered, looking nervously over his shoulder.', 'translation': '"Bir haftadır korku içindeyim efendim," diye fısıldadı Poole endişeyle omzunun üzerinden arkasına bakarak.', 'notes': 'afraid for a week: bir haftadır korku içinde.'}, {'id': 190, 'text': '"I can bear it no longer; I believe there has been foul play!"', 'translation': '"Artık dayanamıyorum; orada bir cinayet, karanlık bir oyun döndüğüne inanıyorum!"', 'notes': 'foul play: cinayet, hileli oyun.'}, {'id': 191, 'text': '"Foul play!" cried Utterson, thoroughly startled; "What kind of foul play could possibly occur?"', 'translation': '"Cinayet mi!" diye haykırdı Utterson iyiden iyiye irkilerek; "Nasıl bir cinayet meydana gelebilir ki?"', 'notes': 'thoroughly startled: iyice irkilmiş/şaşırmış.'}, {'id': 192, 'text': '"I dare not say, sir," was the gloomy answer, "but will you come along with me and see for yourself?"', 'translation': '"Söylemeye dilim varmıyor efendim," oldu kasvetli yanıt, "fakat benimle gelip kendi gözlerinizle görür müsünüz?"', 'notes': 'I dare not say: söylemeye dilim varmıyor.'}, {'id': 193, 'text': 'Utterson put on his heavy coat and hat without another word, accompanying the butler into the gale.', 'translation': 'Utterson tek kelime daha etmeden kalın paltosunu ve şapkasını giydi ve fırtınanın içine doğru uşağa eşlik etti.', 'notes': 'accompanying: eşlik ederek.'}, {'id': 194, 'text': 'It was a wild, cold, seasonable night of March, with a pale moon tilted on her back by the flying clouds.', 'translation': 'Uçuşan bulutların arasında sırtüstü yatmış solgun bir ayın göründüğü, mart ayının vahşi, soğuk ve fırtınalı bir gecesiydi.', 'notes': 'seasonable night: mevsimine uygun gece.'}, {'id': 195, 'text': 'The wind whipped the empty streets, blowing dust into their eyes and rattling the shop shutters.', 'translation': 'Rüzgâr boş sokakları kamçılıyor, gözlerine toz savuruyor ve dükkan kepenklerini takırdatıyordu.', 'notes': 'whipped empty streets: boş sokakları kamçıladı.'}, {'id': 196, 'text': 'London appeared utterly deserted, giving Utterson a sinister premonition of calamity.', 'translation': "Londra tamamen terk edilmiş gibi görünüyordu; bu durum Utterson'a meşum bir felaket önsezisi verdi.", 'notes': 'premonition of calamity: felaket önsezisi.'}, {'id': 197, 'text': "Neither man spoke as they hurried through the gloomy thoroughfares toward Dr. Jekyll's square.", 'translation': "Doktor Jekyll'ın meydanına doğru kasvetli caddelerden hızla geçerken iki adam da tek laf etmedi.", 'notes': 'gloomy thoroughfares: kasvetli ana caddeler.'}, {'id': 198, 'text': 'When they reached the mansion, Poole tapped on the door with a secret, peculiar knock.', 'translation': 'Malikaneye vardıklarında Poole gizli, tuhaf bir vuruşla kapıyı çaldı.', 'notes': 'peculiar knock: tuhaf kapı çalışı.'}, {'id': 199, 'text': 'The door was opened cautiously on the chain before the footman recognized the butler and admitted them.', 'translation': 'Uşak baş uşağı tanıyıp onları içeri almadan önce kapı zincir takılı halde temkinle aralandı.', 'notes': 'opened cautiously on the chain: zincirli halde temkinle açıldı.'}, {'id': 200, 'text': 'Utterson stepped into the hall and found a scene of extraordinary terror waiting within.', 'translation': 'Utterson salona adım attı ve içeride kendisini bekleyen olağanüstü bir dehşet manzarasıyla karşılaştı.', 'notes': 'scene of extraordinary terror: olağanüstü dehşet manzarası.'}]}, {'page_no': 11, 'title': 'The Terrified Servants in the Hall', 'tr_title': 'Salondaki Dehşete Düşmüş Uşaklar', 'vocab_focus': [('servant', 'hizmetkar, uşak'), ('parlor-maid', 'salon hizmetçisi'), ('huddled', 'birbirine sokulmuş'), ('footman', 'uşak, hizmetli'), ('weeping', 'ağlama, gözyaşı dökme'), ('raspy', 'boğuk, hırıltılı'), ('cabinet', 'özel çalışma odası'), ('intruder', 'zorla giren yabancı')], 'sentences': [{'id': 201, 'text': 'The spacious hall was brilliantly lit, with a roaring fire burning upon the hearth.', 'translation': 'Geniş salon ışıl ışıl aydınlatılmıştı ve şöminede gürül gürül bir ateş yanıyordu.', 'notes': 'spacious hall: geniş salon/hol.'}, {'id': 202, 'text': 'Huddled together by the fire like a flock of terrified sheep were all the servants of the household.', 'translation': 'Evin bütün hizmetkarları ürkmüş bir koyun sürüsü gibi şöminenin yanında birbirine sokulmuştu.', 'notes': 'flock of sheep: koyun sürüsü.'}, {'id': 203, 'text': 'The cook, the housemaid, the parlor-maid, and the footman were weeping and whispering in sheer fright.', 'translation': 'Aşçı, oda hizmetçisi, salon kızı ve uşak katıksız bir korku içinde ağlaşıyor ve fısıldaşıyorlardı.', 'notes': 'sheer fright: katıksız korku.'}, {'id': 204, 'text': 'At the sight of Mr. Utterson, the housemaid broke into hysterical whimpering and ran forward.', 'translation': "Bay Utterson'ı görünce oda hizmetçisi histerik bir ağlamaya boğuldu ve öne doğru koştu.", 'notes': 'hysterical whimpering: histerik inilti/ağlama.'}, {'id': 205, 'text': '"Thank God! It\'s Mr. Utterson!" the poor girl cried, clutching her apron.', 'translation': '"Tanrı\'ya şükürler olsun! Bay Utterson geldi!" diye haykırdı zavallı kız önlüğünü kavrayarak.', 'notes': 'clutching apron: önlüğü kavrayarak.'}, {'id': 206, 'text': '"What, what? Are you all here?" the lawyer asked severely; "This is most irregular and improper!"', 'translation': '"Ne oluyor, ne bu hal? Hepiniz burada mısınız?" diye sertçe sordu avukat; "Bu son derece uygunsuz ve nizamsız bir durum!"', 'notes': 'irregular and improper: nizamsız ve uygunsuz.'}, {'id': 207, 'text': '"They\'re all afraid, sir," Poole explained simply; "not one of them dares sleep in their beds tonight."', 'translation': '"Hepsi korkuyor efendim," diye açıkladı Poole sade bir dille; "bu gece hiçbirisi yatağında uyumaya cesaret edemiyor."', 'notes': 'dares sleep: uyumaya cesaret etmek.'}, {'id': 208, 'text': 'Poole took a candle from the table and motioned for Utterson to follow him into the back garden.', 'translation': "Poole masadan bir mum aldı ve arka bahçeye doğru kendisini takip etmesi için Utterson'a işaret etti.", 'notes': 'motioned to follow: takip etmesi için işaret etti.'}, {'id': 209, 'text': 'They stepped out into the stormy courtyard, the candle flame dancing wildly inside its glass lantern.', 'translation': 'Fırtınalı avluya adım attılar; mum alevi cam fenerinin içinde çılgınca dans ediyordu.', 'notes': 'glass lantern: cam fener.'}, {'id': 210, 'text': 'They crossed to the dark laboratory building and entered the silent, cavernous surgical dissecting theater.', 'translation': 'Karanlık laboratuvar binasına geçtiler ve sessiz, mağara gibi cerrahi anatomi salonuna girdiler.', 'notes': 'cavernous dissecting theater: mağara gibi geniş anatomi salonu.'}, {'id': 211, 'text': 'The air was damp and cold, filled with the sharp chemical scents of ether, acid, and embalming fluids.', 'translation': 'Hava nemli ve soğuktu; eter, asit ve mumyalama sıvılarının keskin kimyasal kokularıyla doluydu.', 'notes': 'embalming fluids: mumyalama sıvıları.'}, {'id': 212, 'text': "Poole pointed toward the flight of stairs leading up to the doctor's private cabinet door.", 'translation': 'Poole doktorun özel çalışma odasının kapısına çıkan merdiven basamaklarını işaret etti.', 'notes': 'flight of stairs: merdiven basamakları.'}, {'id': 213, 'text': '"Step softly, sir; I want you to hear for yourself without letting him know we are here," Poole whispered.', 'translation': '"Sessizce basın efendim; burada olduğumuzu ona hissettirmeden kendi kulaklarınızla duymanızı istiyorum," diye fısıldadı Poole.', 'notes': 'step softly: sessizce adım atın.'}, {'id': 214, 'text': 'They crept up the stairs and listened outside the heavy, baize-covered door.', 'translation': 'Merdivenlerden yukarı süzüldüler ve çuha kaplı ağır kapının dışında dinlediler.', 'notes': 'baize-covered door: çuha kaplı kapı.'}, {'id': 215, 'text': 'Inside, footsteps were pacing restlessly to and fro across the wooden floor, never halting for a moment.', 'translation': 'İçeride, ahşap zeminde bir an olsun durmaksızın huzursuz adımlar bir ileri bir geri volta atıyordu.', 'notes': 'pacing restlessly: huzursuzca adımlamak.'}, {'id': 216, 'text': 'Poole knocked firmly upon the panel: "Mr. Utterson is here, sir, and wishes to see you."', 'translation': 'Poole kapı paneline sertçe vurdu: "Bay Utterson burada efendim ve sizi görmek istiyor."', 'notes': 'knocked firmly: sertçe vurdu.'}, {'id': 217, 'text': 'A voice called out from within in a harsh, guttural snarl: "Tell him I cannot see anyone!"', 'translation': 'İçeriden sert, gırtlaktan gelen hırıltılı bir ses bağırdı: "Ona kimseyi göremeyeceğimi söyle!"', 'notes': 'guttural snarl: gırtlaktan gelen hırıltı.'}, {'id': 218, 'text': 'Poole turned to the lawyer, his face white as chalk: "Was that the doctor\'s voice, sir?"', 'translation': 'Poole yüzü tebeşir gibi bembeyaz avukata döndü: "O doktorun sesi miydi efendim?"', 'notes': 'white as chalk: tebeşir gibi beyaz.'}, {'id': 219, 'text': '"It seems much changed," Utterson murmured in shock; "it sounded nothing like Henry Jekyll!"', 'translation': '"Çok değişmiş görünüyor," diye şok içinde mırıldandı Utterson; "hiç Henry Jekyll\'ın sesine benzemiyordu!"', 'notes': 'sounded nothing like: hiç benzemiyordu.'}, {'id': 220, 'text': '"Changed! It is not him at all!" Poole cried; "My master has been murdered, and his killer is locked in that room!"', 'translation': '"Değişmiş mi! O adam kesinlikle o değil!" diye haykırdı Poole; "Efendim katledildi ve katili o odada kilitli duruyor!"', 'notes': 'his killer is locked: katili kilitli duruyor.'}]}, {'page_no': 12, 'title': 'The Chemical Quest and the Masked Creature', 'tr_title': 'Kimyasal Arayış ve Maskeli Yaratık', 'vocab_focus': [('chemist', 'eczacı, kimyager'), ('impurity', 'safsızlık, tortu'), ('crystalline', 'kristal, kristalimsi'), ('dwarfish', 'ufak tefek, cüce gibi'), ('mask', 'maske'), ('scuttering', 'hızla kaçışma'), ('corded', 'damarlı, lifli'), ('axe', 'balta')], 'sentences': [{'id': 221, 'text': 'Utterson and Poole descended the stairs and retreated into the far corner of the dissecting theater.', 'translation': 'Utterson ve Poole merdivenlerden indiler ve teşrih salonunun en uzak köşesine çekildiler.', 'notes': 'retreated into corner: köşeye çekildiler.'}, {'id': 222, 'text': '"If he is not Jekyll, what could possibly motivate an assassin to remain inside the cabinet?" Utterson asked.', 'translation': '"Eğer o kişi Jekyll değilse bir katili çalışma odasının içinde kalmaya ne sevk edebilir ki?" diye sordu Utterson.', 'notes': 'what could motivate: ne sevk edebilir.'}, {'id': 223, 'text': '"All this week, sir, that thing has been crying out day and night for a specific chemical drug," Poole answered.', 'translation': '"Bütün bu hafta boyunca efendim, o yaratık belirli bir kimyasal ilaç için gece gündüz feryat etti," diye yanıtladı Poole.', 'notes': 'specific chemical drug: belirli bir kimyasal ilaç.'}, {'id': 224, 'text': '"Orders were pushed under the door every morning, sending me running to wholesale chemists across London."', 'translation': '"Her sabah kapının altından sipariş pusulaları itildi ve beni Londra\'daki toptancı kimyagerlere koşturdu."', 'notes': 'wholesale chemists: toptancı kimyagerler.'}, {'id': 225, 'text': '"Every time I brought back the required salt, another note would be thrown out, full of fury and despair."', 'translation': '"İstenen kristal tuzu her getirişimde öfke ve çaresizlik dolu bir başka pusula dışarı fırlatılıyordu."', 'notes': 'fury and despair: öfke ve çaresizlik.'}, {'id': 226, 'text': 'Poole pulled a crumpled, tear-stained piece of paper from his pocket and handed it to the lawyer.', 'translation': 'Poole cebinden buruşmuş, gözyaşlarıyla ıslanmış bir kağıt parçası çıkardı ve avukata uzattı.', 'notes': 'crumpled piece of paper: buruşuk kağıt parçası.'}, {'id': 227, 'text': "The handwriting was Dr. Jekyll's, but scrawled with desperate, frantic haste.", 'translation': "El yazısı Doktor Jekyll'a aitti fakat çaresiz ve panik dolu bir aceleyle karalanmıştı.", 'notes': 'scrawled with haste: aceleyle karalanmış.'}, {'id': 228, 'text': 'It was addressed to Messrs. Maw, the famous wholesale chemists on Fleet Street.', 'translation': "Fleet Sokağı'ndaki ünlü toptancı kimyager Maw Şirketi'ne hitaben yazılmıştı.", 'notes': 'addressed to: -e hitaben yazılmış.'}, {'id': 229, 'text': '"For God\'s sake, find me some of the old batch! The salt you sent yesterday is impure and completely useless!"', 'translation': '"Tanrı aşkına bana o eski partiden bulun! Dün gönderdiğiniz tuz saf değil ve tamamen işe yaramaz!"', 'notes': 'impure and useless: saf değil ve işe yaramaz.'}, {'id': 230, 'text': '"My life and my reason depend upon obtaining that original pure supply!"', 'translation': '"Hayatım ve akıl sağlığım o orijinal saf stoğu temin etmeme bağlıdır!"', 'notes': 'reason: akıl, muhakeme.'}, {'id': 231, 'text': '"This is a strange document indeed," Utterson said, adjusting his spectacles in the candlelight.', 'translation': '"Bu gerçekten çok garip bir belge," dedi Utterson mum ışığında gözlüklerini düzelterek.', 'notes': 'adjusting spectacles: gözlüklerini düzelterek.'}, {'id': 232, 'text': '"Have you seen the person who writes these notes, Poole?" the lawyer pressed.', 'translation': '"Bu notları yazan kişiyi hiç gördün mü Poole?" diye üsteledi avukat.', 'notes': 'pressed: üsteledi, ısrarla sordu.'}, {'id': 233, 'text': '"I saw him once, sir, when I came into the theater unexpectedly from the garden," Poole whispered with a shudder.', 'translation': '"Onu bir keresinde, bahçeden anatomi salonuna beklenmedik bir şekilde girdiğimde gördüm efendim," diye fısıldadı Poole ürpererek.', 'notes': 'whispered with a shudder: ürpererek fısıldadı.'}, {'id': 234, 'text': '"He was scuttering among the chemical crates like a rat, wearing a cloth mask over his face."', 'translation': '"Yüzünde bezden bir maskeyle kimyasal sandıklarının arasında bir sıçan gibi hızla koşuşturuyordu."', 'notes': 'scuttering like a rat: sıçan gibi koşuşturan.'}, {'id': 235, 'text': '"When he spotted me, he gave a kind of screech like an animal and whipped up the stairs into the cabinet!"', 'translation': '"Beni fark ettiğinde bir hayvan gibi acayip bir çığlık kopardı ve merdivenleri hızla tırmanıp odaya kaçtı!"', 'notes': 'screech like an animal: hayvan gibi bir çığlık.'}, {'id': 236, 'text': '"Sir, if that was my master, why did he have a mask upon his face?"', 'translation': '"Efendim, eğer o benim efendim idiyse yüzünde neden bir maske vardı?"', 'notes': 'mask upon his face: yüzünde maske.'}, {'id': 237, 'text': '"And why was he so dwarfish and bent, moving like an ape rather than a distinguished gentleman of fifty?"', 'translation': '"Ve elli yaşındaki seçkin bir beyefendiden ziyade bir maymun gibi hareket eden o kadar cüce ve kambur biri miydi o?"', 'notes': 'moving like an ape: maymun gibi hareket eden.'}, {'id': 238, 'text': '"In my heart of hearts, sir, I know that creature was Mr. Edward Hyde!"', 'translation': '"Yüreğimin ta derinliklerinde biliyorum ki efendim, o yaratık Bay Edward Hyde idi!"', 'notes': 'heart of hearts: yüreğinin ta içi/derinlikleri.'}, {'id': 239, 'text': '"If that is true, then we have a moral duty to solve this mystery tonight," Utterson resolved with grim courage.', 'translation': '"Eğer bu doğruysa o halde bu gece bu gizemi çözmek bizim ahlaki görevimizdir," diye karara vardı Utterson çetin bir cesaretle.', 'notes': 'moral duty: ahlaki görev.'}, {'id': 240, 'text': '"We shall break open that door, Poole; go and fetch an axe from the yard!"', 'translation': '"O kapıyı kırıp açacağız Poole; git ve bahçeden bir balta getir!"', 'notes': 'fetch an axe: bir balta getir.'}]}, {'page_no': 13, 'title': 'Breaking the Laboratory Door', 'tr_title': 'Laboratuvar Kapısının Kırılması', 'vocab_focus': [('poker', 'şömine demiri'), ('woodchopper', 'oduncu'), ('mercy', 'merhamet, af'), ('splintering', 'kıymık kıymık parçalanma'), ('panel', 'kapı paneli/ahşabı'), ('hinge', 'menteşe'), ('echoing', 'yankılanan'), ('assault', 'saldırı, hücum')], 'sentences': [{'id': 241, 'text': "Poole returned promptly carrying a heavy woodcutter's axe, while Utterson armed himself with an iron kitchen poker.", 'translation': 'Poole elinde ağır bir oduncu baltasıyla derhal geri döndü; Utterson ise demir bir mutfak maşasıyla silahlandı.', 'notes': "woodcutter's axe: oduncu baltası."}, {'id': 242, 'text': 'Before proceeding, they posted the footman Bradshaw and another sturdy servant at the rear laboratory gate.', 'translation': "İşe koyulmadan önce uşak Bradshaw'u ve güçlü kuvvetli bir başka hizmetkarı arka laboratuvar kapısına yerleştirdiler.", 'notes': 'posted servants: hizmetkarları nöbete koydular.'}, {'id': 243, 'text': 'They instructed them to intercept anyone attempting to escape into the alley with loaded pistols.', 'translation': 'Dolu tabancalarla ara sokağa kaçmaya yeltenecek herkesin yolunu kesmelerini onlara emrettiler.', 'notes': 'intercept anyone: herkesin yolunu kesmek.'}, {'id': 244, 'text': 'With the exits secured, Utterson and Poole ascended the stairs to the cabinet door.', 'translation': 'Çıkışlar güvenceye alındıktan sonra Utterson ve Poole çalışma odası kapısına çıkan merdivenleri tırmandılar.', 'notes': 'exits secured: çıkışlar emniyete alındı.'}, {'id': 245, 'text': 'Inside the room, the restless footsteps continued their ceaseless, rhythmic pacing.', 'translation': 'Odanın içinde huzursuz ayak sesleri dur durak bilmeyen ritmik voltasını sürdürüyordu.', 'notes': 'ceaseless pacing: durmaksızın adımlama.'}, {'id': 246, 'text': 'Utterson knocked loudly: "Jekyll, I demand to see you; open this door immediately!"', 'translation': 'Utterson kapıya sertçe vurdu: "Jekyll, seni görmeyi talep ediyorum; bu kapıyı derhal aç!"', 'notes': 'demand to see: görmeyi talep etmek.'}, {'id': 247, 'text': '"If you do not open by consent, we will use force to enter!" the lawyer warned sternly.', 'translation': '"Eğer rızanla açmazsan içeri girmek için zor kullanacağız!" diye uyardı avukat sertçe.', 'notes': 'open by consent: rızayla açmak.'}, {'id': 248, 'text': 'From within came a desperate, whimpering voice: "Utterson, for God\'s sake, have mercy!"', 'translation': 'İçeriden çaresiz, inleyen bir ses geldi: "Utterson, Tanrı aşkına merhamet et!"', 'notes': 'have mercy: merhamet et, acı.'}, {'id': 249, 'text': 'Utterson gasped: "That is not Jekyll\'s voice—it is Hyde\'s! Down with the door, Poole!"', 'translation': 'Utterson\'ın nefesi kesildi: "O ses Jekyll\'ın sesi değil—Hyde\'ın sesi! Kır şu kapıyı Poole!"', 'notes': 'down with the door: kır kapıyı.'}, {'id': 250, 'text': 'Poole swung the heavy axe with all his physical strength, burying the blade deep into the wooden panel.', 'translation': 'Poole bütün fiziksel gücüyle ağır baltayı savurdu ve namluyu ahşap panelin derinliklerine sapladı.', 'notes': 'buried blade deep: namluyu derine sapladı.'}, {'id': 251, 'text': 'A dreadful, screeching cry like that of a trapped wild animal echoed from inside the room.', 'translation': 'Kapana kısılmış vahşi bir hayvanınki gibi korkunç, tiz bir feryat odanın içinden yankılandı.', 'notes': 'screeching cry: tiz çığlık/feryat.'}, {'id': 252, 'text': 'Again the axe rose and fell, showering the landing with flying splinters of polished red cedar.', 'translation': 'Balta bir kez daha kalkıp indi ve sahanlığı cilalı kızıl sedir ağacının uçuşan kıymıklarıyla doldurdu.', 'notes': 'flying splinters: uçuşan kıymıklar.'}, {'id': 253, 'text': 'The lock sprang loose, but the heavy iron bolts held firm against the assault.', 'translation': 'Kilit yerinden fırladı fakat ağır demir sürgüler saldırıya karşı sağlam durdu.', 'notes': 'lock sprang loose: kilit yerinden fırladı.'}, {'id': 254, 'text': '"Once more, Poole! Put your back into it!" Utterson shouted above the din.', 'translation': '"Bir kez daha Poole! Bütün gücünü ver!" diye bağırdı Utterson gürültünün arasında.', 'notes': 'put your back into it: var gücünle yüklen.'}, {'id': 255, 'text': 'With five thunderous blows, the heavy door shattered completely, tearing the frame from the brickwork.', 'translation': 'Gök gürültüsünü andıran beş darbeyle ağır kapı tamamen parçalandı ve çerçeveyi tuğla duvardan söktü.', 'notes': 'shattered completely: tamamen parçalandı.'}, {'id': 256, 'text': 'The broken door crashed inward onto the carpet with a deafening thud.', 'translation': 'Kırılan kapı sağır edici bir gümlemeyle halının üzerine içeriye doğru devrildi.', 'notes': 'crashed inward: içeriye devrildi.'}, {'id': 257, 'text': 'Utterson and Poole raised their weapons, bracing themselves to confront a savage beast.', 'translation': 'Utterson ve Poole silahlarını kaldırdılar ve vahşi bir canavarla yüzleşmek için kendilerini hazırladılar.', 'notes': 'bracing themselves: kendilerini hazırlayarak.'}, {'id': 258, 'text': 'Instead, an uncanny, profound silence filled the brightly illuminated cabinet.', 'translation': 'Bunun yerine, ışıl ışıl aydınlatılmış çalışma odasını tekinsiz, derin bir sessizlik kapladı.', 'notes': 'uncanny silence: tekinsiz sessizlik.'}, {'id': 259, 'text': 'The fire blazed cheerily in the hearth, and a kettle sang peacefully upon the iron hob.', 'translation': 'Şöminede ateş neşeyle alevleniyordu ve ocak rafının üzerinde bir çaydanlık huzurla ötüyordu.', 'notes': 'kettle sang: çaydanlık ötüyordu.'}, {'id': 260, 'text': 'In the middle of the floor lay the body of a man, writhing in the final, agonizing convulsions of death.', 'translation': 'Zeminin tam ortasında, ölümün o son ve kahredici çırpınışlarıyla kıvranan bir adamın cesedi yatıyordu.', 'notes': 'writhing in convulsions: çırpınışlarla kıvranan.'}]}, {'page_no': 14, 'title': 'The Body of Edward Hyde', 'tr_title': "Edward Hyde'ın Cesedi", 'vocab_focus': [('cyanide', 'siyanür'), ('phial', 'şişecik, tüp'), ('twitching', 'seğirme, çırpınma'), ('oversized', 'büyük gelen, bol'), ('corpse', 'ceset'), ('search', 'arama'), ('dissecting', 'kadavra odası'), ('apparel', 'giysi, kıyafet')], 'sentences': [{'id': 261, 'text': 'Utterson and Poole rushed across the threshold and knelt beside the twitching figure.', 'translation': 'Utterson ve Poole eşikten içeri koştular ve seğiren bedenin yanına diz çöktüler.', 'notes': 'twitching figure: seğiren siluet/beden.'}, {'id': 262, 'text': 'They turned the body upon its back, holding the candle close to reveal the contorted features.', 'translation': 'Çarpılmış yüz hatlarını görmek için mumu yaklaştırarak cesedi sırtüstü çevirdiler.', 'notes': 'contorted features: çarpılmış yüz hatları.'}, {'id': 263, 'text': 'It was Edward Hyde, dressed in clothes tailored for Dr. Jekyll that hung ridiculously loose upon his dwarfish frame.', 'translation': "Doktor Jekyll için dikilmiş ve cüce bedeninin üzerinde gülünç derecede bol duran kıyafetlere bürünmüş kişi Edward Hyde'dı.", 'notes': 'dwarfish frame: cüce cüsse.'}, {'id': 264, 'text': 'The cords of his face moved with a faint shudder, but his glazed eyes were fixed, and life was already extinct.', 'translation': 'Yüzündeki kaslar hafif bir ürpertiyle seğirdi fakat donuk gözleri hareketsizdi ve hayat çoktan sönüp gitmişti.', 'notes': 'life was extinct: hayat sönüp gitmişti.'}, {'id': 265, 'text': 'In his clenched right hand, Hyde gripped a crushed glass phial smelling strongly of bitter almonds.', 'translation': 'Sıkılı sağ elinde Hyde, acı badem gibi yoğun kokan kırılmış bir cam şişeciği tutuyordu.', 'notes': 'smelling of bitter almonds: acı badem kokan.'}, {'id': 266, 'text': '"He has poisoned himself with prussic acid," Utterson whispered in awe; "we have arrived too late to save or punish him."', 'translation': '"Kendisini prusik asitle zehirlemiş," diye dehşetle fısıldadı Utterson; "onu kurtarmak ya da cezalandırmak için çok geç geldik."', 'notes': 'poisoned himself: kendini zehirledi.'}, {'id': 267, 'text': '"The murderer has cheated the gallows by taking his own wicked life."', 'translation': '"Katil kendi alçak canına kıyarak darağacını alt etmiş."', 'notes': 'cheated the gallows: darağacını alt etti.'}, {'id': 268, 'text': '"Now we must find the body of your master, Poole," the lawyer said urgently, rising to his feet.', 'translation': '"Şimdi efendinizin cesedini bulmalıyız Poole," dedi avukat telaşla ayağa kalkarak.', 'notes': 'rising to his feet: ayağa kalkarak.'}, {'id': 269, 'text': 'They searched every corner of the cabinet, examining closets, under desks, and behind velvet curtains.', 'translation': 'Dolapları, masaların altını ve kadife perdelerin arkasını inceleyerek odanın her köşesini aradılar.', 'notes': 'velvet curtains: kadife perdeler.'}, {'id': 270, 'text': 'They descended with lanterns into the gloomy dissecting theater, peering beneath tables and into dark alcoves.', 'translation': 'Fenerlerle kasvetli teşrih salonuna indiler; masaların altlarına ve karanlık girintilere baktılar.', 'notes': 'dark alcoves: karanlık girintiler/oyuklar.'}, {'id': 271, 'text': 'They inspected the damp subterranean cellar, but found only cobwebs, empty crates, and rotting straw.', 'translation': 'Nemli yeraltı mahzenini incelediler fakat yalnızca örümcek ağları, boş sandıklar ve çürüyen saman buldular.', 'notes': 'rotting straw: çürüyen saman.'}, {'id': 272, 'text': 'There was no other corpse, no hidden grave, and not the slightest trace of Dr. Henry Jekyll anywhere.', 'translation': "Başka hiçbir ceset, gizli bir mezar ve hiçbir yerde Doktor Henry Jekyll'dan en ufak bir iz yoktu.", 'notes': 'not the slightest trace: en ufak bir iz bile yok.'}, {'id': 273, 'text': '"Could he have fled?" Utterson wondered aloud, staring at the locked back door leading into the byway.', 'translation': '"Kaçmış olabilir mi?" diye sesli olarak merak etti Utterson, ara sokağa açılan kilitli arka kapıya bakarak.', 'notes': 'wondered aloud: sesli düşündü/merak etti.'}, {'id': 274, 'text': 'Poole pointed to the floor: the key lay rusted and broken beneath the lock, stamped into the stones by a heavy heel.', 'translation': 'Poole zemini işaret etti: Anahtar paslanmış ve kırılmış halde kilidin altında duruyordu; ağır bir ökçeyle taşlara ezilmişti.', 'notes': 'rusted and broken: paslı ve kırık.'}, {'id': 275, 'text': '"No one has escaped through this door, sir; the key has been broken for days!" the butler affirmed.', 'translation': '"Bu kapıdan hiç kimse kaçmamış efendim; anahtar günlerdir kırık duruyor!" diye doğruladı baş uşak.', 'notes': 'broken for days: günlerdir kırık.'}, {'id': 276, 'text': 'They returned in deep perplexity to the upper cabinet, where the corpse of Hyde lay silent upon the rug.', 'translation': "Büyük bir kafa karışıklığı içinde üstteki odaya döndüler; orada Hyde'ın cesedi halının üzerinde sessizce yatıyordu.", 'notes': 'deep perplexity: derin kafa karışıklığı.'}, {'id': 277, 'text': "Utterson approached the doctor's neat writing table, searching for any papers that might explain the mystery.", 'translation': 'Utterson gizemi açıklayabilecek evrakları aramak için doktorun düzenli yazı masasına yaklaştı.', 'notes': 'neat writing table: düzenli yazı masası.'}, {'id': 278, 'text': 'A full-length cheval glass stood in the corner, reflecting their pale faces and the firelit room.', 'translation': 'Köşede onların solgun yüzlerini ve şömineyle aydınlanan odayı yansıtan boydan boya bir ayna duruyordu.', 'notes': 'cheval glass: boy aynası.'}, {'id': 279, 'text': '"This glass has seen some strange things, sir," Poole whispered, shuddering at his own reflection.', 'translation': '"Bu ayna çok tuhaf şeyler gördü efendim," diye fısıldadı Poole kendi yansımasına bakıp ürpererek.', 'notes': 'strange things: tuhaf şeyler.'}, {'id': 280, 'text': '"And none stranger than that which lies upon the carpet," Utterson added in a solemn, grave whisper.', 'translation': '"Ve hiçbiri şu halının üzerinde yatan şeyden daha tuhaf olamaz," diye ekledi Utterson vakur, ciddi bir fısıltıyla.', 'notes': 'solemn grave whisper: vakur ve ağırbaşlı fısıltı.'}]}, {'page_no': 15, 'title': 'The Three Sealed Documents', 'tr_title': 'Mühürlü Üç Belge', 'vocab_focus': [('will', 'vasiyetname'), ('heir', 'mirasçı'), ('beneficiary', 'lehtar, mirasçı'), ('confession', 'itiraf'), ('transcription', 'yazılı kopya'), ('packet', 'paket, tomar'), ('solemn', 'ağırbaşlı, vakur'), ('study', 'çalışma odası')], 'sentences': [{'id': 281, 'text': 'Upon the writing desk, among chemical apparatus and open books, lay a large envelope addressed to Mr. Utterson.', 'translation': "Yazı masasının üzerinde kimyasal aletlerin ve açık kitapların arasında Bay Utterson'a hitaben yazılmış büyük bir zarf duruyordu.", 'notes': 'chemical apparatus: kimyasal aletler.'}, {'id': 282, 'text': 'The lawyer broke the seal with trembling fingers and discovered several enclosures inside.', 'translation': 'Avukat titreyen parmaklarla mührü açtı ve içinde birkaç ek belge keşfetti.', 'notes': 'several enclosures: birkaç ek belge.'}, {'id': 283, 'text': 'The first document was a legal will, drawn up in the exact same terms as the one Utterson had kept in his safe.', 'translation': "İlk belge, Utterson'ın kasasında sakladığı vasiyetnameyle tıpatıp aynı şartlarda düzenlenmiş yasal bir vasiyetnameydi.", 'notes': 'exact same terms: tıpatıp aynı şartlar.'}, {'id': 284, 'text': 'However, with infinite astonishment, Utterson saw that the name of Edward Hyde had been crossed out completely.', 'translation': 'Fakat sonsuz bir hayretle Utterson, Edward Hyde adının tamamen karalandığını gördü.', 'notes': 'infinite astonishment: sonsuz hayret.'}, {'id': 285, 'text': "In its place, written in Dr. Jekyll's neat hand, was the name: Gabriel John Utterson!", 'translation': "Onun yerine Doktor Jekyll'ın düzgün el yazısıyla şu isim yazılmıştı: Gabriel John Utterson!", 'notes': 'neat hand: düzgün el yazısı.'}, {'id': 286, 'text': "Utterson stared at the paper in disbelief: he was now the sole beneficiary of Jekyll's vast wealth.", 'translation': "Utterson inançsızlıkla kağıda bakakaldı: Artık Jekyll'ın muazzam servetinin yegane lehtarı kendisiydi.", 'notes': 'sole beneficiary: tek lehtar/mirasçı.'}, {'id': 287, 'text': '"My head turns round," the lawyer murmured; "Hyde was here all week; why did he not destroy this will?"', 'translation': '"Başım dönüyor," diye mırıldandı avukat; "Hyde bütün hafta buradaydı; neden bu vasiyetnameyi imha etmedi?"', 'notes': 'my head turns round: başım dönüyor.'}, {'id': 288, 'text': '"He must have hated me with passion, yet he left my name untouched upon the paper!"', 'translation': '"Benden büyük bir tutkuyla nefret etmiş olmalı fakat kağıt üzerinde adıma hiç dokunmamış!"', 'notes': 'hated with passion: tutkuyla nefret etti.'}, {'id': 289, 'text': "The second enclosure was a brief, tragic note written that very date in Jekyll's familiar hand.", 'translation': "İkinci ek belge, Jekyll'ın tanıdık el yazısıyla tam o günün tarihiyle yazılmış kısa ve trajik bir nottu.", 'notes': 'brief tragic note: kısa trajik not.'}, {'id': 290, 'text': '"My dear Utterson: when this shall fall into your hands, I shall have disappeared under circumstances I cannot foresee."', 'translation': '"Sevgili Utterson: Bu mektup eline geçtiğinde, öngöremediğim koşullar altında ortadan kaybolmuş olacağım."', 'notes': 'circumstances I cannot foresee: öngöremediğim koşullar.'}, {'id': 291, 'text': '"Go first and read the narrative which Lanyon warned you to keep sealed until my death or disappearance."', 'translation': '"Önce Lanyon\'ın ölümüm ya da kayboluşuma kadar mühürlü tutmanı tembihlediği anlatıyı git ve oku."', 'notes': 'keep sealed: mühürlü tutmak.'}, {'id': 292, 'text': '"And if you wish to learn more of the dark truth, turn to the confession of your unworthy and unhappy friend, Henry Jekyll."', 'translation': '"Ve eğer o karanlık gerçeğe dair daha fazlasını öğrenmek istersen, değersiz ve bahtsız dostun Henry Jekyll\'ın itirafına dön."', 'notes': 'unworthy and unhappy friend: değersiz ve bahtsız dost.'}, {'id': 293, 'text': "The third document was a bulky, thick packet sealed with red wax, bearing the title: 'Henry Jekyll's Full Statement of the Case.'", 'translation': "Üçüncü belge kırmızı balmumuyla mühürlenmiş ve 'Henry Jekyll'ın Olayın Tam Beyanı' başlığını taşıyan kalın, hacimli bir tomar idi.", 'notes': 'bulky thick packet: hacimli kalın paket.'}, {'id': 294, 'text': 'Utterson stood in silence, holding the mysterious confessions of his two oldest friends in his hands.', 'translation': 'Utterson en eski iki dostunun gizemli itiraflarını ellerinde tutarak derin bir sessizlik içinde durdu.', 'notes': 'stood in silence: sessizlik içinde durdu.'}, {'id': 295, 'text': '"Poole," the lawyer said firmly, "I will say nothing of this paper to the police tonight."', 'translation': '"Poole," dedi avukat kararlılıkla, "bu gece polise bu kağıttan hiç bahsetmeyeceğim."', 'notes': 'say nothing to the police: polise hiçbir şey söylememek.'}, {'id': 296, 'text': '"If your master has fled or died, we may at least save his honorable credit and reputation from scandal."', 'translation': '"Efendiniz kaçtıysa ya da öldüyse, hiç değilse onun saygın itibarını bir skandaldan kurtarabiliriz."', 'notes': 'save from scandal: skandaldan kurtarmak.'}, {'id': 297, 'text': '"I shall return to my study to read these two narratives in private before dawn."', 'translation': '"Şafaktan önce bu iki anlatıyı baş başa okumak üzere çalışma odama döneceğim."', 'notes': 'in private: baş başa, gizlice.'}, {'id': 298, 'text': '"Send for the police, report Hyde\'s suicide, and keep all the servants quiet until morning."', 'translation': '"Polisi çağırın, Hyde\'ın intiharını bildirin ve sabaha kadar tüm hizmetkarları sakin tutun."', 'notes': 'report suicide: intiharı bildirmek.'}, {'id': 299, 'text': 'Utterson placed the sealed packets carefully into his coat pocket and stepped out into the night.', 'translation': 'Utterson mühürlü paketleri dikkatle palto cebine koydu ve gecenin içine doğru adım attı.', 'notes': 'sealed packets: mühürlü paketler.'}, {'id': 300, 'text': 'The wind howled across the empty square as the lawyer hurried home to confront the terrifying revelation.', 'translation': 'Avukat o korkunç ifşayla yüzleşmek için evine doğru acele ederken rüzgâr boş meydanda uğulduyordu.', 'notes': 'terrifying revelation: korkunç ifşa/açıklama.'}]}, {'page_no': 16, 'title': "Dr. Lanyon's Extraordinary Narrative", 'tr_title': "Doktor Lanyon'ın Sıradışı Mektubu", 'vocab_focus': [('drawer', 'çekmece'), ('tincture', 'tentür, sıvı çözelti'), ('phosphor', 'fosfor'), ('revolver', 'altıpatlar tabanca'), ('consultation', 'tıbbi danışma'), ('messenger', 'haberci, kurye'), ('crystal', 'kristal tuz'), ('unscientific', 'bilim dışı')], 'sentences': [{'id': 301, 'text': "Sitting alone at his library desk by the glow of a green-shaded lamp, Utterson opened Dr. Lanyon's sealed narrative.", 'translation': "Yeşil abajurlu bir lambanın ışığında kütüphane masasındaki koltuğunda tek başına oturan Utterson, Doktor Lanyon'ın mühürlü anlatısını açtı.", 'notes': 'green-shaded lamp: yeşil abajurlu lamba.'}, {'id': 302, 'text': "The letter began with a vivid recollection of the ninth of January, four days after Jekyll's dinner party.", 'translation': "Mektup Jekyll'ın akşam yemeği partisinden dört gün sonraki dokuz Ocak gününün canlı bir hatırlatmasıyla başlıyordu.", 'notes': 'vivid recollection: canlı hatırlayış.'}, {'id': 303, 'text': 'Lanyon had received an extraordinary registered letter brought by a special messenger from Henry Jekyll.', 'translation': "Lanyon Henry Jekyll'dan özel bir kuryeyle getirilen olağanüstü bir taahhütlü mektup almıştı.", 'notes': 'registered letter: taahhütlü mektup.'}, {'id': 304, 'text': 'The letter pleaded in desperate terms: "Lanyon, my life, my reason, and my soul are all at your mercy!"', 'translation': 'Mektup çaresiz ifadelerle yalvarıyordu: "Lanyon; hayatım, aklım ve ruhum tamamen senin merhametine kalmış durumda!"', 'notes': 'at your mercy: senin merhametine kalmış.'}, {'id': 305, 'text': '"If you fail me tonight, I am lost forever; postpone all other engagements and drive straight to my house!"', 'translation': '"Bu gece beni yarı yolda bırakırsan sonsuza dek mahvolurum; diğer bütün randevularını ertele ve doğruca evime sür!"', 'notes': 'postpone engagements: randevuları/işleri ertelemek.'}, {'id': 306, 'text': "Jekyll instructed Lanyon to meet Poole, force open the door of the private cabinet, and pull out the fourth drawer marked 'E'.", 'translation': "Jekyll Lanyon'a Poole ile buluşmasını, özel odanın kapısını zorla açmasını ve 'E' ile işaretlenmiş dördüncü çekmeceyi çekip almasını emrediyordu.", 'notes': 'fourth drawer: dördüncü çekmece.'}, {'id': 307, 'text': 'Lanyon was to bring the entire drawer back to his own consulting room in Cavendish Square exactly as it was.', 'translation': "Lanyon çekmeceyi olduğu gibi Cavendish Meydanı'ndaki kendi muayenehanesine geri getirecekti.", 'notes': 'consulting room: muayenehane.'}, {'id': 308, 'text': '"At midnight, a man will present himself in my name; hand him the drawer, and your role is finished."', 'translation': '"Gece yarısı benim adıma bir adam çıkıp gelecek; çekmeceyi ona ver ve görevin tamamlansın."', 'notes': 'present himself: çıkıp gelmek, kendini takdim etmek.'}, {'id': 309, 'text': 'Lanyon felt certain that his old friend had gone hopelessly insane, but he decided to honor the bizarre request.', 'translation': 'Lanyon eski dostunun umutsuz bir şekilde delirdiğinden emin oldu fakat bu tuhaf isteği yerine getirmeye karar verdi.', 'notes': 'hopelessly insane: umutsuzca deli/çıldırmış.'}, {'id': 310, 'text': 'Accompanied by a locksmith and Poole, Lanyon broke into the cabinet and retrieved the designated drawer.', 'translation': 'Bir çilingir ve Poole eşliğinde Lanyon odaya girdi ve belirtilen çekmeceyi alıp getirdi.', 'notes': 'designated drawer: belirtilen çekmece.'}, {'id': 311, 'text': 'Returning home, Lanyon examined the contents of the drawer under his bright desk lamp.', 'translation': 'Eve dönen Lanyon çalışma masasının parlak lambası altında çekmecenin içindekileri inceledi.', 'notes': 'contents of the drawer: çekmecenin içindekiler.'}, {'id': 312, 'text': 'Inside were several small packets of white crystalline salts that emitted a curious chemical odor.', 'translation': 'İçinde tuhaf bir kimyasal koku yayan beyaz kristalimsi tuzlardan oluşan birkaç küçük paket vardı.', 'notes': 'white crystalline salts: beyaz kristal tuzlar.'}, {'id': 313, 'text': 'There was also a glass phial containing a blood-red, pungent liquid that seemed highly volatile.', 'translation': 'Ayrıca son derece uçucu görünen kan kırmızısı, keskin kokulu bir sıvı içeren bir cam şişecik vardı.', 'notes': 'blood-red pungent liquid: kan kırmızısı keskin kokulu sıvı.'}, {'id': 314, 'text': 'Beside the chemicals lay a notebook recording a series of dates and brief remarks spanning several years.', 'translation': 'Kimyasalların yanında birkaç yıla yayılan bir dizi tarihi ve kısa notları kaydeden bir defter duruyordu.', 'notes': 'spanning several years: birkaç yıla yayılan.'}, {'id': 315, 'text': "Entries like 'total failure', 'double dose', and 'successful trial' appeared repeatedly throughout the pages.", 'translation': "'Tam başarısızlık', 'çift doz' ve 'başarılı deneme' gibi kayıtlar sayfalar boyunca defalarca yer alıyordu.", 'notes': 'successful trial: başarılı deneme.'}, {'id': 316, 'text': 'Lanyon could make neither head nor tail of these scientific notes, which seemed like mere medical eccentricity.', 'translation': 'Sıradan bir tıbbi tuhaflık gibi görünen bu bilimsel notlardan Lanyon ne baş ne de son çıkarabildi.', 'notes': 'neither head nor tail: ne başı ne sonu belli olmayan.'}, {'id': 317, 'text': 'As midnight approached, Lanyon placed a loaded revolver upon his desk, determined to be prepared for any danger.', 'translation': 'Gece yarısı yaklaşırken Lanyon her türlü tehlikeye karşı hazırlıklı olmaya kararlı bir şekilde masasının üzerine dolu bir tabanca koydu.', 'notes': 'loaded revolver: dolu altıpatlar tabanca.'}, {'id': 318, 'text': 'The church bells of London were striking twelve when a light, sharp knock sounded on the front door.', 'translation': "Londra'nın kilise çanları on ikiyi vururken ön kapıda hafif ve sert bir tıkırtı duyuldu.", 'notes': 'striking twelve: on ikiyi vururken.'}, {'id': 319, 'text': 'Lanyon answered the door himself and found a small, cloaked figure standing upon the porch in the darkness.', 'translation': 'Kapıyı bizzat Lanyon açtı ve karanlıkta verandada pelerinli ufak tefek bir siluetin durduğunu gördü.', 'notes': 'cloaked figure: pelerinli siluet.'}, {'id': 320, 'text': 'It was Edward Hyde, shivering with nervous impatience, stepping into the hallway of his unsuspecting host.', 'translation': 'Asabi bir sabırsızlıkla titreyen ve hiçbir şeyden şüphelenmeyen ev sahibinin koridoruna adım atan kişi Edward Hyde idi.', 'notes': 'nervous impatience: asabi sabırsızlık.'}]}, {'page_no': 17, 'title': "The Midnight Transmutation before Lanyon's Eyes", 'tr_title': "Lanyon'ın Gözleri Önündeki Gece Yarısı Dönüşümü", 'vocab_focus': [('compound', 'bileşik'), ('effervescence', 'köpürme, gaz çıkışı'), ('draught', 'yudum, iksir'), ('stagger', 'sendelemek'), ('metamorphosis', 'başkalaşım, dönüşüm'), ('shattered', 'mahvolmuş, yıkılmış'), ('unhinge', 'aklını başından almak'), ('prostration', 'tükenmişlik, çöküntü')], 'sentences': [{'id': 321, 'text': 'Lanyon admitted the small, cloaked stranger into his brightly illuminated consulting room.', 'translation': 'Lanyon pelerinli ufak tefek yabancıyı ışıl ışıl aydınlatılmış muayenehanesine buyur etti.', 'notes': 'brightly illuminated: ışıl ışıl aydınlatılmış.'}, {'id': 322, 'text': 'Hyde was trembling with a dreadful, feverish excitement, his eyes darting hungrily around the chamber.', 'translation': 'Hyde korkunç, hummalı bir heyecanla titriyordu; gözleri açgözlülükle odanın etrafında fır dönüyordu.', 'notes': 'feverish excitement: hummalı heyecan.'}, {'id': 323, 'text': 'At the sight of the drawer standing upon the table, he sprang forward with a sobbing gasp of relief.', 'translation': 'Masanın üzerinde duran çekmeceyi görünce hıçkırıklı bir rahatlama nefesiyle öne atıldı.', 'notes': 'sobbing gasp of relief: hıçkırıklı rahatlama nefesi.'}, {'id': 324, 'text': 'With shaking hands, Hyde measured a few drops of the red tincture into a glass graduated cylinder.', 'translation': 'Titreyen ellerle Hyde dereceli bir cam silindire kırmızı tentürden birkaç damla koydu.', 'notes': 'graduated cylinder: dereceli silindir.'}, {'id': 325, 'text': 'He then added a small portion of the white crystalline salt from one of the paper packets.', 'translation': 'Ardından kağıt paketlerden birinden az miktarda beyaz kristal tuz ekledi.', 'notes': 'crystalline salt: kristal tuz.'}, {'id': 326, 'text': 'The mixture began immediately to boil and effervesce, flashing with strange, chromatic luminescence.', 'translation': 'Karışım derhal kaynamaya ve köpürmeye başladı; tuhaf, renkli bir ışıltıyla parıldadı.', 'notes': 'effervesce: köpürmek, gaz çıkarmak.'}, {'id': 327, 'text': 'The liquid shifted from dark crimson to deep purple, finally settling into a clear, glowing emerald green.', 'translation': 'Sıvı koyu kızıla, ardından koyu mora döndü; nihayet berrak, parıldayan bir zümrüt yeşiline büründü.', 'notes': 'glowing emerald green: parıldayan zümrüt yeşili.'}, {'id': 328, 'text': 'Hyde turned to Lanyon, his repulsive features twisted into a mocking, insolent smile.', 'translation': "Hyde Lanyon'a döndü; itici yüz hatları alaycı, küstah bir gülümsemeyle çarpılmıştı.", 'notes': 'insolent smile: küstah gülümseme.'}, {'id': 329, 'text': '"And now, Dr. Lanyon, will you let me take this glass and depart without questioning?" Hyde asked softly.', 'translation': '"Ve şimdi Doktor Lanyon, bu kadehi alıp sorgusuz sualsiz ayrılmama izin verecek misiniz?" diye sordu Hyde usulca.', 'notes': 'depart without questioning: sorgusuz sualsiz ayrılmak.'}, {'id': 330, 'text': '"Or has your greed of curiosity mastered your judgment? Will you witness a marvel that will stagger your soul?"', 'translation': '"Yoksa merak hırsınız aklınıza galip mi geldi? Ruhunuzu sarsacak bir mucizeye tanıklık edecek misiniz?"', 'notes': 'stagger your soul: ruhunuzu sarsacak.'}, {'id': 331, 'text': '"I have gone too far in this bizarre business to pause now," Lanyon replied with stubborn defiance.', 'translation': '"Bu tuhaf işte artık duraklamak için çok fazla ileri gittim," diye yanıtladı Lanyon inatçı bir meydan okumayla.', 'notes': 'stubborn defiance: inatçı meydan okuma.'}, {'id': 332, 'text': '"Then behold!" cried the creature, raising the glass and draining the glowing potion in one swallow.', 'translation': '"O halde seyret!" diye haykırdı yaratık; kadehi kaldırıp parıldayan iksiri bir yudumda dikti.', 'notes': 'draining the potion: iksiri kafaya dikmek.'}, {'id': 333, 'text': 'He uttered a terrible shriek, staggered across the room, and clutched desperately at the edge of the table.', 'translation': 'Korkunç bir çığlık attı, odanın içinde sendeledi ve çaresizce masanın kenarına tutundu.', 'notes': 'staggered across: sendeleyerek geçti.'}, {'id': 334, 'text': 'His eyes rolled back, his mouth opened gasping for air, and his face turned black as coal.', 'translation': 'Gözleri geriye kaydı, ağzı hava almak için çırpınarak açıldı ve yüzü kömür gibi karardı.', 'notes': 'turned black as coal: kömür gibi karardı.'}, {'id': 335, 'text': "Before Lanyon's horror-stricken eyes, the creature seemed to swell, its limbs stretching and bones cracking audibly.", 'translation': "Lanyon'ın dehşete düşmüş gözleri önünde yaratık şişer gibi oldu; uzuvları gerildi ve kemikleri duyulur şekilde çatırdayıp kırıldı.", 'notes': 'horror-stricken eyes: dehşet içindeki gözler.'}, {'id': 336, 'text': 'The dark, dwarfish monster melted away, expanding into the tall, broad-shouldered frame of a mature gentleman.', 'translation': 'O karanlık, cüce canavar eriyip gitti; olgun bir beyefendinin uzun boylu, geniş omuzlu cüssesine dönüştü.', 'notes': 'melted away: eriyip yok oldu.'}, {'id': 337, 'text': 'Lanyon leaped to his feet with an unearthly scream, pressing his back against the wall in sheer terror.', 'translation': 'Lanyon dünya dışı bir çığlıkla ayağa fırladı; katıksız bir dehşetle sırtını duvara dayadı.', 'notes': 'unearthly scream: dünya dışı/tekinsiz çığlık.'}, {'id': 338, 'text': '"O God!" Lanyon screamed again and again; "O God! O God!"', 'translation': '"Aman Tanrım!" diye haykırdı Lanyon defalarca; "Aman Tanrım! Aman Tanrım!"', 'notes': 'screamed again and again: tekrar tekrar haykırdı.'}, {'id': 339, 'text': 'For there before him, pale, shaken, and half-fainting, stood Dr. Henry Jekyll himself!', 'translation': "Çünkü karşısında solgun, sarsılmış ve bayılmak üzere olan kişi bizzat Doktor Henry Jekyll'ın kendisiydi!", 'notes': 'half-fainting: bayılmak üzere.'}, {'id': 340, 'text': '"What he told me in the next hour, I cannot bring my pen to write," Lanyon concluded; "my life is shaken to its roots!"', 'translation': '"Takip eden bir saatte bana anlattıklarını yazmaya elim varmıyor," diye bitirdi Lanyon; "hayatım köklerinden sarsıldı!"', 'notes': 'shaken to its roots: köklerinden sarsılmış.'}]}, {'page_no': 18, 'title': "Henry Jekyll's Statement: The Duality of Man", 'tr_title': "Henry Jekyll'ın Beyanı: İnsanın Çift Doğası", 'vocab_focus': [('duality', 'ikilik, çift doğa'), ('inclination', 'eğilim, meyil'), ('debauchery', 'sefahat, ahlaksızlık'), ('hypocrisy', 'ikiyüzlülük'), ('dissociate', 'ayırmak, ayrıştırmak'), ('incongruous', 'uyumsuz, bağdaşmaz'), ('perception', 'algı'), ('aspirations', 'yüce arzular, idealler')], 'sentences': [{'id': 341, 'text': "Utterson laid down Lanyon's dreadful letter and opened the thick, handwritten confession of Henry Jekyll.", 'translation': "Utterson Lanyon'ın o korkunç mektubunu bıraktı ve Henry Jekyll'ın kalın, el yazması itirafını açtı.", 'notes': 'handwritten confession: el yazması itiraf.'}, {'id': 342, 'text': 'Jekyll began by recounting his privileged youth: born to a great fortune, naturally industrious, and fond of social respect.', 'translation': 'Jekyll ayrıcalıklı gençliğini anlatarak başlıyordu: Büyük bir servetin içine doğmuş, doğası gereği çalışkan ve toplumsal saygıya düşkün biriydi.', 'notes': 'privileged youth: ayrıcalıklı gençlik.'}, {'id': 343, 'text': 'Yet he possessed an intense, secret craving for wild, reckless pleasure that he felt compelled to hide.', 'translation': 'Fakat saklamak zorunda hissettiği çılgın, pervasız zevklere yönelik yoğun ve gizli bir arzu taşıyordu.', 'notes': 'secret craving: gizli arzu/iştah.'}, {'id': 344, 'text': 'Ashamed of his sensual desires, he concealed his pleasures behind an austere facade of solemn morality.', 'translation': 'Şehvet dolu arzularından utandığı için zevklerini vakur bir ahlakın sert dış görünüşünün ardına gizledi.', 'notes': 'austere facade: sert dış görünüş.'}, {'id': 345, 'text': 'Thus, while still a young man, he had already committed himself to a profound and agonizing double existence.', 'translation': 'Böylece daha genç bir adamken bile kendisini derin ve kahredici bir çifte varoluşa çoktan mahkûm etmişti.', 'notes': 'double existence: çifte varoluş.'}, {'id': 346, 'text': 'In public, he was a revered doctor of medicine, but in private, he indulged in degrading debauchery.', 'translation': 'Toplum önünde saygıdeğer bir tıp doktoruydu fakat gizlide alçaltıcı sefahatlere dalıyordu.', 'notes': 'revered doctor: saygıdeğer doktor.'}, {'id': 347, 'text': 'As a scientist, he reflected deeply on the perpetual moral civil war raging within the human soul.', 'translation': 'Bir bilim insanı olarak insan ruhunun içinde kopan o ebedi ahlaki iç savaş üzerine derin derin düşündü.', 'notes': 'moral civil war: ahlaki iç savaş.'}, {'id': 348, 'text': '"With every day that passed, I drew steadily nearer to that truth: that man is not truly one, but truly two!"', 'translation': '"Geçen her günle birlikte şu gerçeğe durmaksızın yaklaştım: İnsan aslında tek değil, aslında ikidir!"', 'notes': 'truly two: aslında iki (kişi).'}, {'id': 349, 'text': 'He perceived that two distinct natures—the noble angel and the savage beast—were locked together in mortal combat.', 'translation': 'İki ayrı doğanın—asil melekle vahşi canavarın—ölümcül bir mücadelede birbirine kilitlendiğini gördü.', 'notes': 'mortal combat: ölümcül dövüş/mücadele.'}, {'id': 350, 'text': 'He dreamed of using chemical science to dissociate these two incongruous identities into two separate physical forms.', 'translation': 'Bu iki uyumsuz kimliği iki ayrı fiziksel bedene ayırmak için kimya bilimini kullanmayı hayal etti.', 'notes': 'dissociate identities: kimlikleri ayrıştırmak.'}, {'id': 351, 'text': '"If each could be housed in separate identities, life would be relieved of all unbearable hypocrisy,"', 'translation': '"Eğer her biri ayrı kimliklere yerleştirilebilseydi, hayat o katlanılmaz ikiyüzlülükten kurtulurdu,"', 'notes': 'unbearable hypocrisy: katlanılmaz ikiyüzlülük.'}, {'id': 352, 'text': '"The good self could walk steadfastly on the upward path, doing good and aspiring to heavenly virtue,"', 'translation': '"İyi benlik kararlılıkla yüce yolda yürüyebilir, iyilik yapıp ilahi erdemi arzulayabilirdi,"', 'notes': 'upward path: yüce/yukarı yol.'}, {'id': 353, 'text': '"While the lower self could go its own way, indulging in pleasures without staining the honorable doctor\'s name."', 'translation': '"Aşağılık benlik ise kendi yoluna gidebilir, saygın doktorun adını lekelemeden zevklerine dalabilirdi."', 'notes': 'staining the name: adı lekelemek.'}, {'id': 354, 'text': 'Jekyll studied ancient alchemy and modern chemistry, seeking a drug that could strip the flesh of its outer shell.', 'translation': 'Jekyll bedeni o dış kabuğundan soyup çıkarabilecek bir ilaç arayarak kadim simyayı ve modern kimyayı inceledi.', 'notes': 'ancient alchemy: kadim simya.'}, {'id': 355, 'text': 'He discovered that certain volatile salts reacted violently with an acidic tincture to affect the nervous system.', 'translation': 'Belirli uçucu tuzların sinir sistemini etkilemek için asidik bir tentürle şiddetli tepkimeye girdiğini keşfetti.', 'notes': 'volatile salts: uçucu tuzlar.'}, {'id': 356, 'text': 'He purchased a large quantity of white crystalline salt from a wholesale chemist on Fleet Street.', 'translation': "Fleet Sokağı'ndaki bir toptancı kimyagerden yüklü miktarda beyaz kristal tuz satın aldı.", 'notes': 'large quantity: yüklü miktar.'}, {'id': 357, 'text': 'He knew that the experiment involved mortal danger, for a miscalculation could result in instant death.', 'translation': 'Deneyin ölümcül bir tehlike barındırdığını biliyordu zira yapılacak bir hesap hatası anında ölümle sonuçlanabilirdi.', 'notes': 'mortal danger: ölümcül tehlike.'}, {'id': 358, 'text': 'Yet the temptation of making a discovery so profound overcame all lingering terror.', 'translation': 'Fakat böylesine derin bir keşif yapmanın ayartısı, geriye kalan bütün korkuların üstesinden geldi.', 'notes': 'overcame all terror: tüm korkuyu yendi.'}, {'id': 359, 'text': 'Late one midnight, alone in his private cabinet, Jekyll prepared the bubbling green compound.', 'translation': 'Gece yarısı geç saatlerde özel odasında tek başına olan Jekyll köpüren yeşil bileşiği hazırladı.', 'notes': 'bubbling compound: köpüren bileşik.'}, {'id': 360, 'text': 'Steeling his courage with a desperate prayer, he raised the glowing potion to his lips and drank it down.', 'translation': 'Çaresiz bir duayla cesaretini toplayarak parıldayan iksiri dudaklarına götürdü ve kafaya dikti.', 'notes': 'steeling his courage: cesaretini toplayarak.'}]}, {'page_no': 19, 'title': 'The First Transmutation and the Birth of Hyde', 'tr_title': "İlk Dönüşüm ve Hyde'ın Doğuşu", 'vocab_focus': [('potion', 'iksir'), ('transmutation', 'dönüşüm, başkalaşım'), ('nausea', 'mide bulantısı'), ('agony', 'büyük acı, ızdırap'), ('lightness', 'hafiflik'), ('wickedness', 'kötülük, alçaklık'), ('mirror', 'ayna'), ('antidote', 'panzehir')], 'sentences': [{'id': 361, 'text': 'The most racking pangs succeeded the draught: a grinding in the bones, deadly nausea, and a horror of the spirit.', 'translation': 'İksirin ardından en kahredici sancılar geldi: Kemiklerde bir öğütülme, ölümcül bir mide bulantısı ve ruhun dehşeti.', 'notes': 'racking pangs: kahredici sancılar.'}, {'id': 362, 'text': 'He felt as if his soul was being torn violently from its earthly tenement by demonic hands.', 'translation': 'Sanki ruhu şeytani eller tarafından dünyevi hanesinden şiddetle sökülüp alınıyormuş gibi hissetti.', 'notes': 'earthly tenement: dünyevi mesken/beden.'}, {'id': 363, 'text': 'Then, quite suddenly, the physical agony subsided, replaced by an extraordinary sensation of delight.', 'translation': 'Ardından ansızın o fiziksel acı dindi; yerini olağanüstü bir haz hissine bıraktı.', 'notes': 'sensation of delight: haz/zevk hissi.'}, {'id': 364, 'text': 'He felt younger, lighter, and physically happier than he had ever felt in his entire life.', 'translation': 'Bütün hayatında hiç hissetmediği kadar genç, hafif ve bedenen mutlu hissetti.', 'notes': 'physically happier: bedenen daha mutlu.'}, {'id': 365, 'text': 'Within his breast, there stirred an intoxicating sense of reckless freedom and boundless sensual appetite.', 'translation': 'Göğsünün içinde sarhoş edici bir pervasız özgürlük hissi ve sınırsız bir şehvet iştahı kıpırdandı.', 'notes': 'intoxicating freedom: sarhoş edici özgürlük.'}, {'id': 366, 'text': 'He felt conscious of a heady recklessness, but at the same time, he knew himself to be tenfold more wicked.', 'translation': 'Baş döndürücü bir umursamazlığın bilincindeydi fakat aynı anda on kat daha kötücül olduğunu da biliyordu.', 'notes': 'tenfold more wicked: on kat daha kötücül.'}, {'id': 367, 'text': 'Every moral restraint, every voice of conscience and duty, had been dissolved like salt in water.', 'translation': 'Her ahlaki kısıtlama, her vicdan ve görev sesi sudaki tuz gibi eriyip gitmişti.', 'notes': 'dissolved like salt: tuz gibi eridi.'}, {'id': 368, 'text': 'He looked down at his clothes: they hung loose around him, for his physical stature had shrunk noticeably.', 'translation': 'Giysilerine baktı: Üzerinde bol duruyorlardı zira fiziksel boyu fark edilir derecede kısalmıştı.', 'notes': 'stature had shrunk: boyu/cüssesi kısalmıştı.'}, {'id': 369, 'text': 'He crossed the floor to the tall cheval glass to behold the results of his miraculous transmutation.', 'translation': 'Mucizevi başkalaşımının sonuçlarını görmek için odanın karşısındaki yüksek boy aynasına yürüdü.', 'notes': 'miraculous transmutation: mucizevi başkalaşım.'}, {'id': 370, 'text': 'Looking into the mirror, Jekyll beheld Edward Hyde for the very first time.', 'translation': "Aynaya bakan Jekyll bizzat ilk kez Edward Hyde'ı gördü.", 'notes': 'for the very first time: tam da ilk kez.'}, {'id': 371, 'text': 'The figure was dwarfish and slender, with coarse hair and hands that were corded and hairy.', 'translation': 'Siluet cüce gibi ve ince yapılıydı; kaba saçları, damarlı ve kıllı elleri vardı.', 'notes': 'corded and hairy hands: damarlı ve kıllı eller.'}, {'id': 372, 'text': 'Upon the visage was written an unmistakable expression of pure, concentrated evil.', 'translation': 'Çehresinde saf ve yoğunlaşmış kötülüğün inkâr edilemez ifadesi yazılıydı.', 'notes': 'concentrated evil: yoğunlaşmış kötülük.'}, {'id': 373, 'text': 'Yet when Jekyll gazed upon this monstrous reflection, he felt no instinctive revulsion.', 'translation': 'Fakat Jekyll bu canavarca yansımaya baktığında hiçbir içgüdüsel tiksinti duymadı.', 'notes': 'instinctive revulsion: içgüdüsel tiksinti.'}, {'id': 374, 'text': 'Instead, he felt a strange, welcoming leap of recognition: this creature was natural and human, a part of himself!', 'translation': 'Bunun yerine garip, sevinçli bir kabulleniş sıçraması hissetti: Bu yaratık doğal ve insaniydi; kendisinin bir parçasıydı!', 'notes': 'leap of recognition: tanıma/kabullenme sevinci.'}, {'id': 375, 'text': "Hyde was smaller and younger because the evil side of Jekyll's nature had been much less exercised.", 'translation': "Hyde daha ufak ve gençti çünkü Jekyll'ın doğasının kötü tarafı çok daha az işletilmiş ve çalıştırılmıştı.", 'notes': 'much less exercised: çok daha az çalıştırılmış/kullanılmış.'}, {'id': 376, 'text': 'Whereas all other human beings are a mingled commingling of good and evil, Hyde was purely evil alone.', 'translation': 'Oysa diğer bütün insanlar iyilik ve kötülüğün karmaşık bir karışımıyken, Hyde tek başına sırf kötülükten ibaretti.', 'notes': 'purely evil alone: tek başına sırf kötülük.'}, {'id': 377, 'text': 'The most dangerous part of the experiment remained: could he reverse the transformation back to Henry Jekyll?', 'translation': "Deneyin en tehlikeli kısmı hâlâ duruyordu: Dönüşümü tersine çevirip tekrar Henry Jekyll'a dönebilir miydi?", 'notes': 'reverse the transformation: dönüşümü tersine çevirmek.'}, {'id': 378, 'text': 'Hurrying back to the table, he mixed a second draught of the green potion and swallowed it eagerly.', 'translation': 'Telaşla masaya dönerek yeşil iksirden ikinci bir yudum hazırladı ve onu hevesle dikti.', 'notes': 'swallowed eagerly: hevesle yuttu.'}, {'id': 379, 'text': 'Once again came the racking bone pain, the dizziness, and the tearing convulsions.', 'translation': 'Bir kez daha o kahredici kemik ağrısı, baş dönmesi ve parçalayıcı çırpınmalar geldi.', 'notes': 'tearing convulsions: parçalayıcı çırpınmalar.'}, {'id': 380, 'text': 'When he opened his eyes and looked into the mirror, Dr. Henry Jekyll was looking back at him, restored and whole.', 'translation': 'Gözlerini açıp aynaya baktığında eski haline dönmüş ve tastamam Doktor Henry Jekyll ona geri bakıyordu.', 'notes': 'restored and whole: eski haline dönmüş ve eksiksiz.'}]}, {'page_no': 20, 'title': 'The Double Life and the Growing Beast', 'tr_title': 'Çifte Yaşam ve Büyüyen Canavar', 'vocab_focus': [('indulgence', 'zevk düşkünlüğü'), ('sovereign', 'hükümdar, mutlak'), ('depravity', 'ahlaki çöküntü, sapkınlık'), ('impenetrable', 'geçilmez, aşılmaz'), ('safeguard', 'güvence, kalkan'), ('monstrous', 'canavarca'), ('callous', 'nasırlı, duygusuz, taş kalpli'), ('reckless', 'pervasız, umursamaz')], 'sentences': [{'id': 381, 'text': 'Exulting in his discovery, Jekyll felt that he had solved the greatest riddle of human existence.', 'translation': 'Keşfiyle gururlanan Jekyll, insan varoluşunun en büyük bilmecesini çözdüğünü hissetti.', 'notes': 'solved greatest riddle: en büyük bilmeceyi çözdü.'}, {'id': 382, 'text': 'He now possessed an impenetrable mantle of disguise that granted him absolute moral immunity.', 'translation': 'Artık kendisine mutlak ahlaki dokunulmazlık sağlayan delinmez bir kılık değiştirme zırhına sahipti.', 'notes': 'moral immunity: ahlaki dokunulmazlık.'}, {'id': 383, 'text': 'To protect his alter ego, he furnished the discreet apartment in Soho and hired an unprincipled housekeeper.', 'translation': "Öteki benliğini korumak için Soho'daki o gözlerden uzak daireyi döşedi ve ahlaksız bir hizmetçi kadın tuttu.", 'notes': 'unprincipled housekeeper: ahlaksız hizmetçi kadın.'}, {'id': 384, 'text': 'He instructed Poole and the household servants that Mr. Hyde was to have free entry and total authority.', 'translation': "Poole ve evdeki hizmetkarlara Bay Hyde'ın serbest giriş hakkına ve tam yetkiye sahip olacağını bildirdi.", 'notes': 'total authority: tam yetki.'}, {'id': 385, 'text': "He drafted the controversial will in Utterson's care as an insurance policy in case he should ever be trapped as Hyde.", 'translation': "Hyde olarak hapsolması ihtimaline karşı bir sigorta poliçesi kabilinden Utterson'ın korumasındaki o tartışmalı vasiyetnameyi hazırladı.", 'notes': 'insurance policy: sigorta poliçesi/güvencesi.'}, {'id': 386, 'text': 'Whenever the lust for pleasure seized Dr. Jekyll, he had only to drink the potion in his laboratory.', 'translation': "Zevk arzusu Doktor Jekyll'ı ne zaman ele geçirse laboratuvarındaki iksiri içmesi yeterliydi.", 'notes': 'lust for pleasure: zevk/haz tutkusu.'}, {'id': 387, 'text': 'In a moment, the respected doctor vanished, and Edward Hyde stepped out into the foggy London night.', 'translation': 'Bir anda saygın doktor kayboluyor ve Edward Hyde sisli Londra gecesine adım atıyordu.', 'notes': 'stepped out: dışarı adım attı.'}, {'id': 388, 'text': 'Hyde roamed through the vilest dens of vice, indulging in cruelties that Jekyll would never have dared conceive.', 'translation': "Hyde ahlaksızlığın en aşağılık batakhanelerinde fink atıyor; Jekyll'ın hayal bile etmeye cesaret edemeyeceği zalimliklere dalıyordu.", 'notes': 'vilest dens of vice: fuhuş/günah batakhaneleri.'}, {'id': 389, 'text': "When the night's debauchery was completed, Hyde slipped back through the laboratory door into the cabinet.", 'translation': 'Gecenin sefahati tamamlandığında Hyde laboratuvar kapısından içeri süzülüp çalışma odasına dönüyordu.', 'notes': 'slipped back: gizlice geri süzüldü.'}, {'id': 390, 'text': 'He swallowed the antidote, and within minutes, Dr. Henry Jekyll was sitting peacefully at his morning breakfast table.', 'translation': 'Panzehiri yutuyor ve birkaç dakika içinde Doktor Henry Jekyll sabah kahvaltı masasında huzurla oturuyordu.', 'notes': 'swallowed antidote: panzehiri yuttu.'}, {'id': 391, 'text': 'Jekyll persuaded himself that he was completely blameless for the crimes committed by Edward Hyde.', 'translation': 'Jekyll Edward Hyde tarafından işlenen suçlardan ötürü kendisinin tamamen kusursuz olduğuna kendini inandırdı.', 'notes': 'completely blameless: tamamen kusursuz/suçsuz.'}, {'id': 392, 'text': '"It was Hyde after all, and Hyde alone, that was guilty; Jekyll was no worse; his virtues remained intact!"', 'translation': '"Sonuçta suçlu olan Hyde\'dı, yalnızca Hyde idi; Jekyll daha kötü değildi; erdemleri el değmemiş olarak duruyordu!"', 'notes': 'virtues remained intact: erdemleri el değmemiş kaldı.'}, {'id': 393, 'text': 'Yet with every transformation, Hyde grew increasingly callous, monstrous, and aggressive.', 'translation': 'Fakat her dönüşümle birlikte Hyde giderek daha taş kalpli, canavarca ve saldırgan bir hal aldı.', 'notes': 'increasingly callous: giderek taş kalpli/duygusuz.'}, {'id': 394, 'text': 'His pleasures took on a dark, sadistic edge that thrilled the beast with animal satisfaction.', 'translation': 'Zevkleri canavarı hayvani bir tatminle coşturan karanlık, sadist bir boyut kazandı.', 'notes': 'sadistic edge: sadist bir boyut/yön.'}, {'id': 395, 'text': "It was during one of these nocturnal excursions that Hyde trampled the little girl, leading to Enfield's confrontation.", 'translation': "Hyde'ın küçük kızı çiğneyip Enfield ile yüzleşmesine yol açan olay işte bu gece gezintilerinden birinde yaşandı.", 'notes': 'nocturnal excursions: gece gezintileri.'}, {'id': 396, 'text': "To pay off the angry family, Hyde had drawn a cheque from Jekyll's account, nearly exposing the secret.", 'translation': "Öfkeli ailenin parasını ödemek için Hyde Jekyll'ın hesabından bir çek çekmiş ve neredeyse sırrı açığa vurmuştu.", 'notes': 'nearly exposing: neredeyse ifşa eden.'}, {'id': 397, 'text': "Frightened by the near-discovery, Jekyll opened a separate bank account in Edward Hyde's own name.", 'translation': "Neredeyse yakalanacak olmaktan korkan Jekyll, Edward Hyde'ın kendi adına ayrı bir banka hesabı açtı.", 'notes': 'separate bank account: ayrı banka hesabı.'}, {'id': 398, 'text': 'He believed that with this additional precaution, his secret sanctuary would remain forever safe from exposure.', 'translation': 'Bu ilave tedbirle gizli sığınağının ifşa olmaktan sonsuza dek güvende kalacağına inanıyordu.', 'notes': 'additional precaution: ilave tedbir.'}, {'id': 399, 'text': 'He did not foresee that the physical laws of nature were already preparing a terrifying retribution.', 'translation': 'Doğanın fiziksel yasalarının çoktan korkunç bir intikam hazırladığını öngöremedi.', 'notes': 'terrifying retribution: korkunç ceza/intikam.'}, {'id': 400, 'text': 'The beast was no longer a temporary mask; it was clawing its way permanently into the light.', 'translation': 'Canavar artık geçici bir maske değildi; kalıcı olarak ışığa çıkmak için tırnaklarıyla yol açıyordu.', 'notes': 'clawing its way: tırnaklarıyla yol açarak.'}]}, {'page_no': 21, 'title': 'The Involuntary Awakening and the Broken Mirror', 'tr_title': 'İstemsiz Uyanış ve Kırılan Denge', 'vocab_focus': [('involuntary', 'istemsiz, elinde olmadan'), ('bedclothes', 'yatak örtüleri'), ('knuckle', 'parmak eklemi'), ('sinewy', 'kaslı, lifli'), ('usurpation', 'gasp etme, zorla ele geçirme'), ('crisis', 'kriz, bunalım'), ('renounce', 'vazgeçmek, feragat etmek'), ('repentance', 'tövbe, pişmanlık')], 'sentences': [{'id': 401, 'text': "A terrifying event occurred in the early winter of that year that shattered Jekyll's complacency forever.", 'translation': "O yılın kış başlarında Jekyll'ın rehavetini sonsuza dek yerle bir eden korkunç bir olay meydana geldi.", 'notes': 'shattered complacency: rehaveti/rahatlığı tuzla buz etti.'}, {'id': 402, 'text': 'He woke one morning in his own bed in the square, feeling rested and pleasantly drowsy.', 'translation': 'Bir sabah meydandaki kendi yatağında dinlenmiş ve tatlı bir uyku mahmurluğu içinde uyandı.', 'notes': 'pleasantly drowsy: tatlı bir mahmurluk içinde.'}, {'id': 403, 'text': 'Looking down casually at his hand lying upon the linen sheet, an icy spasm of horror struck his heart.', 'translation': 'Keten çarşafın üzerinde duran eline öylesine baktığında buz gibi bir dehşet spazmı yüreğine saplandı.', 'notes': 'icy spasm: buz gibi spazm/sancı.'}, {'id': 404, 'text': 'The hand of Henry Jekyll was large, firm, white, and comely, well known to all his medical colleagues.', 'translation': "Henry Jekyll'ın eli iri, sağlam, beyaz ve biçimliydi; bütün tıp meslektaşları tarafından iyi bilinirdi.", 'notes': 'white and comely: beyaz ve yakışıklı/biçimli.'}, {'id': 405, 'text': 'The hand that lay before his eyes was lean, corded, knuckly, of a dusky pallor, and thickly shaded with dark hair.', 'translation': 'Gözlerinin önünde duran el ise cılız, damarlı, boğumlu, esmer bir solgunlukta ve koyu kıllarla kaplıydı.', 'notes': 'shaded with dark hair: koyu kıllarla kaplı.'}, {'id': 406, 'text': 'It was the unmistakable hand of Edward Hyde!', 'translation': "Edward Hyde'ın o inkâr edilemez eliydi bu!", 'notes': 'unmistakable hand: şüphe götürmez el.'}, {'id': 407, 'text': 'Jekyll stared at it with jumping eyes: he had gone to bed as Dr. Henry Jekyll, but had awakened as Edward Hyde!', 'translation': 'Jekyll faltaşı gibi açılmış gözlerle eline bakakaldı: Yatağa Doktor Henry Jekyll olarak girmiş fakat Edward Hyde olarak uyanmıştı!', 'notes': 'jumping eyes: faltaşı gibi açılmış gözler.'}, {'id': 408, 'text': 'He had transformed in his sleep without drinking a single drop of the chemical draught!', 'translation': 'Kimyasal iksirden tek bir damla bile içmeden uykusunda dönüşüm geçirmişti!', 'notes': 'without drinking a drop: tek damla içmeden.'}, {'id': 409, 'text': 'Terror seized his soul: if the servants saw him in this dwarfish form, he would be instantly unmasked.', 'translation': 'Dehşet ruhunu esir aldı: Eğer hizmetkarlar onu bu cüce kılıkta görselerdi maskesi anında düşerdi.', 'notes': 'instantly unmasked: maskesi anında düşerdi.'}, {'id': 410, 'text': 'Pulling the blanket around his small frame, he slipped cautiously down the back stairs and across the courtyard.', 'translation': 'Battaniyeyi ufak cüssesine sararak arka merdivenlerden usulca aşağı süzüldü ve avluyu geçti.', 'notes': 'slipped cautiously: temkinle süzüldü.'}, {'id': 411, 'text': 'Reaching the cabinet, he prepared a double dose of the potion with frantic haste and swallowed it down.', 'translation': 'Çalışma odasına ulaşınca çılgın bir aceleyle iksirden çift doz hazırladı ve kafaya dikti.', 'notes': 'frantic haste: panik dolu acele.'}, {'id': 412, 'text': 'After agonizing convulsions, the form of Dr. Jekyll was restored, but his mind remained shattered by dread.', 'translation': "Kahredici çırpınmaların ardından Doktor Jekyll'ın bedeni geri geldi fakat zihni dehşetle paramparça kalmıştı.", 'notes': 'shattered by dread: dehşetle paramparça.'}, {'id': 413, 'text': 'He realized with horrifying clarity that the balance of his nature was permanently overthrown.', 'translation': 'Korkunç bir berraklıkla doğasının dengesinin kalıcı olarak altüst olduğunu anladı.', 'notes': 'permanently overthrown: kalıcı olarak altüst edilmiş.'}, {'id': 414, 'text': 'Originally, it had required great effort to transform into Hyde, and returning to Jekyll was effortless.', 'translation': "Başlangıçta Hyde'a dönüşmek büyük bir çaba gerektiriyor ve Jekyll'a dönmek zahmetsiz oluyordu.", 'notes': 'great effort: büyük çaba.'}, {'id': 415, 'text': 'Now, Hyde was asserting dominance: the body reverted to the beast spontaneously during sleep or weakness.', 'translation': 'Şimdi ise Hyde hakimiyet kuruyordu: Beden uykuda ya da zayıflık anında kendiliğinden canavara dönüşüyordu.', 'notes': 'reverted spontaneously: kendiliğinden geri döndü.'}, {'id': 416, 'text': 'He was being slowly consumed and replaced by the creature he had foolishly created.', 'translation': 'Ahmakça yarattığı o yaratık tarafından yavaş yavaş tüketiliyor ve onun yerine geçiriliyordu.', 'notes': 'slowly consumed: yavaşça tüketilen.'}, {'id': 417, 'text': '"I must choose between them once and for all," Jekyll recorded in his agony; "the two can no longer coexist."', 'translation': '"Aralarında kesin ve nihai bir seçim yapmalıyım," diye kaydetti Jekyll ızdırabı içinde; "artık ikisi bir arada var olamaz."', 'notes': 'once and for all: kesin ve nihai olarak.'}, {'id': 418, 'text': 'He chose the elderly, discontented, but honorable doctor, renouncing the intoxicating liberty of Edward Hyde.', 'translation': "Edward Hyde'ın sarhoş edici özgürlüğünden feragat ederek yaşlı, hoşnutsuz fakat onurlu doktoru seçti.", 'notes': 'renouncing liberty: özgürlükten feragat ederek.'}, {'id': 419, 'text': 'He locked the door of the laboratory from the garden, trampled the key beneath his heel, and took a vow of virtue.', 'translation': 'Laboratuvarın bahçeye açılan kapısını kilitledi, anahtarı ökçesinin altında ezdi ve bir erdem yemini etti.', 'notes': 'took a vow of virtue: erdem yemini etti.'}, {'id': 420, 'text': 'For two months, he kept his resolution, but the caged beast within him was clawing desperately for freedom.', 'translation': 'İki ay boyunca kararına sadık kaldı fakat içindeki o kafese kapatılmış canavar özgürlük için çaresizce tırnak atıyordu.', 'notes': 'caged beast: kafesteki canavar.'}]}, {'page_no': 22, 'title': 'The Carew Murder and the Starved Devil', 'tr_title': 'Carew Cinayeti ve Aç Bırakılan Şeytan', 'vocab_focus': [('suppress', 'bastırmak'), ('caged', 'kafese kapatılmış'), ('paroxysm', 'öfke nöbeti'), ('savagery', 'vahşilik'), ('cane', 'baston'), ('hang-man', 'cellat'), ('atonement', 'kefaret, günah çıkarma'), ('sanctity', 'kutsallık, masumiyet')], 'sentences': [{'id': 421, 'text': 'For sixty days, Dr. Jekyll lived as a moral saint, subduing every evil impulse through sheer willpower.', 'translation': 'Altmış gün boyunca Doktor Jekyll katıksız bir irade gücüyle her kötü dürtüyü bastırarak ahlaklı bir aziz gibi yaşadı.', 'notes': 'subduing every evil impulse: her kötü dürtüyü bastırarak.'}, {'id': 422, 'text': 'Yet his inner demon was not destroyed; it was merely starved and enraged by its long confinement.', 'translation': 'Fakat içindeki iblis yok edilmemişti; uzun tutsaklığı yüzünden yalnızca aç bırakılmış ve öfkelendirilmişti.', 'notes': 'starved and enraged: aç bırakılmış ve öfkelenmiş.'}, {'id': 423, 'text': 'In a moment of fatal spiritual weariness in October, Jekyll sat in his cabinet and began to rationalize his desires.', 'translation': 'Ekim ayında ölümcül bir ruhani yorgunluk anında Jekyll çalışma odasında oturdu ve arzularını meşrulaştırmaya başladı.', 'notes': 'rationalize desires: arzuları meşrulaştırmak.'}, {'id': 424, 'text': "He thought of Hyde's thrilling, forbidden adventures and felt an overwhelming temptation to escape once more.", 'translation': "Hyde'ın heyecan verici, yasak maceralarını düşündü ve bir kez daha kaçmak için karşı konulmaz bir ayartı hissetti.", 'notes': 'overwhelming temptation: karşı konulmaz ayartı.'}, {'id': 425, 'text': 'With trembling hands, he prepared the green draught, believing he could control the beast with ease.', 'translation': 'Canavarı kolaylıkla kontrol edebileceğine inanarak titreyen ellerle yeşil iksiri hazırladı.', 'notes': 'control the beast: canavarı kontrol etmek.'}, {'id': 426, 'text': '"My devil had been long caged," Jekyll confessed; "he came out roaring!"', 'translation': '"Benim şeytanım uzun süre kafese kapatılmıştı," diye itiraf etti Jekyll; "kükreyerek dışarı çıktı!"', 'notes': 'came out roaring: kükreyerek çıktı.'}, {'id': 427, 'text': 'Hyde burst into existence with a furious thirst for bloodshed and destruction.', 'translation': 'Hyde kan dökme ve yıkım için öfkeli bir susuzlukla varoluşa daldı.', 'notes': 'thirst for bloodshed: kan dökme susuzluğu.'}, {'id': 428, 'text': 'Walking through the moonlit streets near the river, Hyde was approached politely by Sir Danvers Carew.', 'translation': "Nehir yakınındaki mehtaplı sokaklarda yürürken Sör Danvers Carew Hyde'a kibarca yaklaştı.", 'notes': 'approached politely: kibarca yaklaştı.'}, {'id': 429, 'text': "The elderly gentleman's innocence and refined gentleness enraged the demon beyond all endurance.", 'translation': 'Yaşlı beyefendinin masumiyeti ve zarif kibarlığı iblisi her türlü tahammülün ötesinde öfkelendirdi.', 'notes': 'refined gentleness: zarif kibarlık.'}, {'id': 430, 'text': 'In a paroxysm of demonic rage, Hyde struck Carew with the heavy cane, knocking him into the roadway.', 'translation': "Şeytani bir öfke nöbeti içinde Hyde ağır bastonla Carew'a vurdu ve onu yola devirdi.", 'notes': 'paroxysm of rage: öfke nöbeti.'}, {'id': 431, 'text': 'He trampled the body beneath his heels, glorying in the crunch of breaking bones and the splashing blood.', 'translation': 'Kırılan kemiklerin çıtırtısından ve sıçrayan kandan haz duyarak cesedi ökçelerinin altında çiğnedi.', 'notes': 'glorying in the crunch: çıtırtıdan haz alarak.'}, {'id': 432, 'text': 'Only when the heavy cane snapped in half did the madman cease his senseless assault.', 'translation': 'Deli ancak o ağır baston ortadan ikiye kırıldığında bu anlamsız saldırısına son verdi.', 'notes': 'senseless assault: anlamsız saldırı.'}, {'id': 433, 'text': "Looking down at the mutilated corpse, an icy shock of clarity pierced through Hyde's bloodlust.", 'translation': "Parçalanmış cesede baktığında buz gibi bir kavrayış şoku Hyde'ın kan tutkusunu yardı geçti.", 'notes': 'mutilated corpse: parçalanmış ceset.'}, {'id': 434, 'text': 'He had murdered a prominent Member of Parliament; the police would hunt him with relentless fury to the gallows!', 'translation': 'Önde gelen bir milletvekilini katletmişti; polis onu amansız bir öfkeyle darağacına kadar kovalayacaktı!', 'notes': 'hunt to the gallows: darağacına kadar kovalamak.'}, {'id': 435, 'text': "Hyde fled through the foggy lanes to Soho, burned his personal papers, and rushed back to Jekyll's laboratory.", 'translation': "Hyde sisli sokaklardan Soho'ya kaçtı, kişisel evraklarını yaktı ve Jekyll'ın laboratuvarına geri koştu.", 'notes': 'foggy lanes: sisli ara sokaklar.'}, {'id': 436, 'text': 'He swallowed the antidote and collapsed upon the floor, weeping in horror as the gentle Dr. Jekyll returned.', 'translation': 'Panzehiri yuttu ve o narin Doktor Jekyll geri dönerken dehşet içinde ağlayarak yere yığıldı.', 'notes': 'collapsed upon floor: yere yığıldı.'}, {'id': 437, 'text': 'Jekyll looked upon his bloody hands and shuddered in utter revulsion at the monstrous crime.', 'translation': 'Jekyll kanlı ellerine baktı ve o canavarca cinayet karşısında mutlak bir tiksintiyle ürperdi.', 'notes': 'utter revulsion: mutlak tiksinti.'}, {'id': 438, 'text': 'He spent the remaining hours of the night upon his knees, weeping bitter tears of repentance and shame.', 'translation': 'Gecenin kalan saatlerini dizlerinin üzerinde, acı pişmanlık ve utanç gözyaşları dökerek geçirdi.', 'notes': 'tears of repentance: tövbe/pişmanlık gözyaşları.'}, {'id': 439, 'text': 'He forged the letter from Hyde to convince Utterson that the murderer had fled forever.', 'translation': "Katilin sonsuza dek kaçtığına Utterson'ı ikna etmek için Hyde'ın ağzından o sahte mektubu kaleme aldı.", 'notes': 'forged the letter: sahte mektup yazdı/düzenledi.'}, {'id': 440, 'text': 'Jekyll swore on his immortal soul that Edward Hyde was dead to him, never to be resurrected again.', 'translation': 'Jekyll ölümsüz ruhu üzerine ant içti ki Edward Hyde kendisi için ölmüştü ve bir daha asla diriltilmeyecekti.', 'notes': 'never to be resurrected: bir daha asla diriltilmemek.'}]}, {'page_no': 23, 'title': "The Daylight Transformation in Regent's Park", 'tr_title': "Regent's Park'ta Gündüz Dönüşümü", 'vocab_focus': [('broad daylight', 'gün ortası, güpegündüz'), ('shudder', 'ürperti'), ('qualm', 'tedirginlik, vicdan azabı'), ('gallows', 'darağacı'), ('desperation', 'çaresizlik'), ('fugitive', 'firari, kaçak'), ('hotel', 'otel'), ('messenger', 'haberci, kurye')], 'sentences': [{'id': 441, 'text': 'Following the Carew murder, Jekyll sought to atone for the horror through devoted acts of charity and kindness.', 'translation': 'Carew cinayetinin ardından Jekyll kendini adadığı hayır ve iyilik eylemleriyle bu dehşetin kefaretini ödemeye çalıştı.', 'notes': 'atone for the horror: dehşetin kefaretini ödemek.'}, {'id': 442, 'text': 'He visited the sick, funded orphanages, and lived in open, cheerful communion with his fellow men.', 'translation': 'Hastaları ziyaret etti, yetimhaneleri finanse etti ve hemcinsleriyle açık, neşeli bir birliktelik içinde yaşadı.', 'notes': 'cheerful communion: neşeli birliktelik.'}, {'id': 443, 'text': 'Yet his fundamental spiritual flaw—pride—remained unhealed within his ambitious heart.', 'translation': 'Fakat onun o temel ruhani kusuru—kibir—hırslı kalbinin içinde iyileşmeden duruyordu.', 'notes': 'fundamental flaw: temel kusur.'}, {'id': 444, 'text': "On a fine, clear morning in January, Jekyll strolled through the sunny pathways of Regent's Park.", 'translation': "Ocak ayının berrak, güzel bir sabahında Jekyll Regent's Park'ın güneşli patikalarında gezintiye çıktı.", 'notes': 'sunny pathways: güneşli patikalar.'}, {'id': 445, 'text': 'Sitting upon a wooden bench, he felt a surge of smug self-righteousness warming his spirit.', 'translation': 'Ahşap bir bankta otururken ruhunu ısıtan kendini beğenmiş bir erdemlilik dalgası hissetti.', 'notes': 'smug self-righteousness: kendini beğenmiş erdemlilik.'}, {'id': 446, 'text': '"After all, I am better than other men," he thought proudly; "I have conquered my sins and conquered evil."', 'translation': '"Sonuçta ben diğer insanlardan daha iyiyim," diye gururla düşündü; "Günahlarımı fethettim ve kötülüğü alt ettim."', 'notes': 'conquered evil: kötülüğü alt etti.'}, {'id': 447, 'text': 'At that very instant of boastful arrogance, a sudden, deadly shudder racked his entire spine.', 'translation': 'O böbürlenen kibir anının tam ortasında, ani ve ölümcül bir ürperti bütün omurgasını sarstı.', 'notes': 'boastful arrogance: böbürlenen kibir.'}, {'id': 448, 'text': 'A sickening qualm of nausea swept over him, followed by a terrifying lightness in his physical frame.', 'translation': 'Mide bulandırıcı bir bulantı dalgası onu kapladı; ardından fiziksel bedeninde korkunç bir hafiflik belirdi.', 'notes': 'sickening qualm: mide bulandırıcı his/sancı.'}, {'id': 449, 'text': 'The nausea passed, leaving him trembling; he looked down at his clothes in mounting horror.', 'translation': 'Bulantı geçti ve onu titrer halde bıraktı; artan bir dehşetle giysilerine aşağıya doğru baktı.', 'notes': 'mounting horror: artan dehşet.'}, {'id': 450, 'text': 'His trousers draped loosely around shrunken legs; his coat hung baggy over narrow, dwarfed shoulders.', 'translation': 'Pantolonu küçülmüş bacaklarının etrafında bolca sarkıyordu; paltosu daralmış cüce omuzlarının üzerinde torba gibi duruyordu.', 'notes': 'dwarfed shoulders: cüce omuzlar.'}, {'id': 451, 'text': 'Looking at his hand resting on his knee, he saw the dark, hairy, sinewy claw of Edward Hyde!', 'translation': "Dizinin üzerinde duran eline baktığında Edward Hyde'ın koyu, kıllı, damarlı pençesini gördü!", 'notes': 'sinewy claw: damarlı/kaslı pençe.'}, {'id': 452, 'text': 'He had transformed into the hunted murderer in broad daylight, in an open public park!', 'translation': 'Güpegündüz, halka açık bir parkın ortasında aranan katile dönüşmüştü!', 'notes': 'in broad daylight: güpegündüz.'}, {'id': 453, 'text': 'A cold sweat broke upon his brow as he realized the sheer impossibility of his situation.', 'translation': 'Durumunun katıksız imkânsızlığını anladığında alnından soğuk terler boşaldı.', 'notes': 'cold sweat broke: soğuk ter boşaldı.'}, {'id': 454, 'text': 'He was Edward Hyde, with the entire police force of London hunting him for the murder of Danvers Carew.', 'translation': 'O Edward Hyde idi ve tüm Londra polis teşkilatı Danvers Carew cinayeti yüzünden onun peşindeydi.', 'notes': 'entire police force: tüm polis teşkilatı.'}, {'id': 455, 'text': 'He could not walk to his own house without being recognized, reported, and arrested on the spot.', 'translation': 'Tanınmadan, ihbar edilmeden ve derhal tutuklanmadan kendi evine yürümesi mümkün değildi.', 'notes': 'arrested on the spot: olay yerinde tutuklanmak.'}, {'id': 456, 'text': 'Even if he reached the square, his servants had orders to summon the police if Hyde ever appeared.', 'translation': 'Meydana ulaşsa bile Hyde görülecek olursa uşaklarının polisi çağırma yönünde emirleri vardı.', 'notes': 'summon the police: polisi çağırmak.'}, {'id': 457, 'text': 'Yet his drugs were locked in the cabinet above the laboratory, and without them, he was trapped as Hyde forever.', 'translation': 'Oysa ilaçları laboratuvarın üzerindeki odada kilitliydi ve onlar olmaksızın sonsuza dek Hyde olarak kapana kısılmıştı.', 'notes': 'trapped forever: sonsuza dek kapana kısılmış.'}, {'id': 458, 'text': 'Suddenly, a brilliant stroke of cunning crossed his desperate mind: Dr. Hastie Lanyon!', 'translation': 'Ansızın çaresiz zihninde parlak bir kurnazlık şimşeği çaktı: Doktor Hastie Lanyon!', 'notes': 'stroke of cunning: kurnazlık hamlesi/fikri.'}, {'id': 459, 'text': 'Hyde hailed a closed cab, drove to an obscure private hotel in Portland Street, and ordered a private sitting room.', 'translation': "Hyde kapalı bir fayton çağırdı, Portland Sokağı'ndaki ücra özel bir otele sürdürdü ve özel bir oturma odası tuttu.", 'notes': 'obscure private hotel: ücra özel otel.'}, {'id': 460, 'text': "Writing in Jekyll's handwriting, he composed the desperate letters to Lanyon and Poole, sending them by express messengers.", 'translation': "Jekyll'ın el yazısıyla Lanyon ve Poole'a o çaresiz mektupları kaleme aldı ve onları acele kuryelerle gönderdi.", 'notes': 'express messengers: acele kuryeler.'}]}, {'page_no': 24, 'title': 'The Fatal Depletion of the Impure Salt', 'tr_title': 'Saf Olmayan Tuzun Tükenişi ve Felaket', 'vocab_focus': [('depletion', 'tükenme, bitme'), ('exhaustion', 'tükenmişlik'), ('impure', 'saf olmayan, kusurlu'), ('ingredient', 'bileşen, madde'), ('catalyst', 'katalizör'), ('hopeless', 'umutsuz'), ('agony', 'ızdırap'), ('catastrophe', 'felaket')], 'sentences': [{'id': 461, 'text': "After transforming back to Jekyll in Lanyon's presence, the doctor returned home in the grey light of dawn.", 'translation': "Lanyon'ın huzurunda tekrar Jekyll'a dönüştükten sonra doktor şafağın gri ışığında evine döndü.", 'notes': 'grey light of dawn: şafağın gri ışığı.'}, {'id': 462, 'text': "He had survived that crisis, but the horrifying price of his salvation was the destruction of Lanyon's sanity.", 'translation': "O krizi atlatmıştı fakat kurtuluşunun korkunç bedeli Lanyon'ın akıl sağlığının yıkımı olmuştu.", 'notes': 'price of salvation: kurtuluşun bedeli.'}, {'id': 463, 'text': 'Within days, the ultimate nightmare closed in upon Jekyll with unrelenting, suffocating cruelty.', 'translation': "Birkaç gün içinde o nihai kâbus amansız, boğucu bir zalimlikle Jekyll'ın tepesine çöktü.", 'notes': 'suffocating cruelty: boğucu zalimlik.'}, {'id': 464, 'text': 'The involuntary transformations began occurring not just during sleep, but every few hours throughout the day!', 'translation': 'İstemsiz dönüşümler yalnızca uykuda değil, gün boyunca birkaç saatte bir gerçekleşmeye başladı!', 'notes': 'involuntary transformations: istemsiz dönüşümler.'}, {'id': 465, 'text': 'He could no longer step outside his cabinet without risking an immediate, spontaneous metamorphosis.', 'translation': 'Anında kendiliğinden bir başkalaşım riskine girmeden çalışma odasının dışına adım bile atamıyordu.', 'notes': 'spontaneous metamorphosis: kendiliğinden başkalaşım.'}, {'id': 466, 'text': 'Even while pacing across the floor or writing at his desk, the racking shudder would suddenly seize his limbs.', 'translation': 'Zeminde volta atarken veya masasında yazarken bile o kahredici ürperti ansızın uzuvlarını yakalıyordu.', 'notes': 'racking shudder: sarsıcı ürperti.'}, {'id': 467, 'text': 'To maintain his human shape for even two hours, he had to consume double and triple doses of the green drug.', 'translation': 'İki saatliğine bile insan formunu koruyabilmek için yeşil ilaçtan çift ve üç kat dozlar tüketmek zorunda kaldı.', 'notes': 'maintain human shape: insan formunu korumak.'}, {'id': 468, 'text': 'Then came the final, mortal catastrophe: his stock of the white crystalline salt began to run low.', 'translation': 'Derken o son ve ölümcül felaket geldi çattı: Beyaz kristal tuz stoku azalmaya başladı.', 'notes': 'stock began to run low: stok azalmaya başladı.'}, {'id': 469, 'text': 'Jekyll sent Poole with urgent orders to Messrs. Maw on Fleet Street, purchasing a fresh supply of the salt.', 'translation': "Jekyll tuzdan taze bir tedarik satın almak için Fleet Sokağı'ndaki Maw Şirketi'ne Poole'u acil siparişlerle gönderdi.", 'notes': 'fresh supply: taze stok/tedarik.'}, {'id': 470, 'text': 'With trembling hands, Jekyll mixed the new salt with the red tincture, awaiting the familiar boiling effervescence.', 'translation': 'Titreyen ellerle Jekyll yeni tuzu kırmızı tentürle karıştırdı; o tanıdık kaynayan köpürmeyi bekledi.', 'notes': 'familiar effervescence: tanıdık köpürme.'}, {'id': 471, 'text': 'To his utter despair, the mixture remained completely inert: it produced no fizz, no heat, and no change of color!', 'translation': 'Büyük bir umutsuzlukla gördü ki karışım tamamen tepkisiz kaldı: Hiçbir köpürme, ısı ve renk değişimi üretmedi!', 'notes': 'completely inert: tamamen tepkisiz.'}, {'id': 472, 'text': 'He drank it in desperation, but it produced none of the agony and none of the miraculous transformation.', 'translation': 'Çaresizlik içinde onu içti fakat ne o acıyı ne de o mucizevi dönüşümü hiç üretmedi.', 'notes': 'drank in desperation: çaresizlikle içti.'}, {'id': 473, 'text': 'Thinking the chemists had made a mistake, he sent Poole to every other wholesale chemist across the metropolis.', 'translation': "Kimyagerlerin bir hata yaptığını düşünerek Poole'u metropoldeki diğer tüm toptancı kimyagerlere gönderdi.", 'notes': 'wholesale chemist: toptancı kimyager.'}, {'id': 474, 'text': 'Every sample brought back by Poole was tested with frantic hope, and every sample failed completely.', 'translation': 'Poole tarafından getirilen her numune çılgın bir umutla test edildi ve her numune tamamen başarısız oldu.', 'notes': 'frantic hope: panik dolu umut.'}, {'id': 475, 'text': "Then, and only then, did the horrifying chemical truth dawn upon Dr. Henry Jekyll's shattered mind.", 'translation': "İşte o zaman ve ancak o zaman o korkunç kimyasal gerçek Doktor Henry Jekyll'ın yıkılmış zihnine dank etti.", 'notes': 'truth dawned upon: gerçek zihnine dank etti.'}, {'id': 476, 'text': 'His original supply of salt, purchased years before, had contained an unknown, accidental impurity!', 'translation': 'Yıllar önce satın aldığı o orijinal tuz stoku, bilinmeyen ve tesadüfi bir safsızlık/tortu içeriyordu!', 'notes': 'accidental impurity: tesadüfi safsızlık/kusur.'}, {'id': 477, 'text': 'It was that unknown impurity alone that had catalyzed the miraculous transmutation of his physical frame!', 'translation': 'Onun fiziksel bedeninin o mucizevi başkalaşımını tetikleyen yalnızca o bilinmeyen safsızlık idi!', 'notes': 'catalyzed the transmutation: başkalaşımı tetikledi.'}, {'id': 478, 'text': 'All the new salts were chemically pure, and therefore utterly powerless to affect the metamorphosis.', 'translation': 'Yeni tuzların tümü kimyasal olarak saftı ve bu nedenle başkalaşımı etkilemekte tamamen güçsüzdü.', 'notes': 'chemically pure: kimyasal olarak saf.'}, {'id': 479, 'text': 'There was no other impure batch in all of London, nor anywhere on the face of the earth.', 'translation': "Tüm Londra'da ve yeryüzünde bir başka saf olmayan parti mevcut değildi.", 'notes': 'face of the earth: yeryüzü.'}, {'id': 480, 'text': 'The discovery had been an accidental miracle, and the miracle could never be repeated again.', 'translation': 'Keşif tesadüfi bir mucize olmuştu ve o mucize bir daha asla tekrarlanamazdı.', 'notes': 'never repeated again: bir daha asla tekrarlanamaz.'}]}, {'page_no': 25, 'title': 'The Final Hour of Henry Jekyll', 'tr_title': "Henry Jekyll'ın Son Saati ve Veda", 'vocab_focus': [('inevitable', 'kaçınılmaz'), ('perdition', 'ebedi mahvoluş, cehennem'), ('confession', 'itiraf'), ('suicide', 'intihar'), ('cyanide', 'siyanür'), ('deliverance', 'kurtuluş'), ('judgment', 'hüküm, yargı'), ('curtain', 'perde')], 'sentences': [{'id': 481, 'text': 'Jekyll sits at his writing desk, measuring out the final remaining drops of the original impure salt.', 'translation': 'Jekyll yazı masasında oturuyor; o orijinal kusurlu tuzun kalan son damlalarını ölçüyor.', 'notes': 'measuring out: ölçerek ayırıyor.'}, {'id': 482, 'text': 'This final draught will keep him in human shape for only a few more fleeting, precious minutes.', 'translation': 'Bu son yudum onu yalnızca birkaç kısacık, kıymetli dakika daha insan suretinde tutacaktır.', 'notes': 'fleeting minutes: akıp giden dakikalar.'}, {'id': 483, 'text': 'When the effects of this final potion wear off, the transformation into Edward Hyde will be irrevocable and permanent.', 'translation': "Bu son ilacın etkisi geçtiğinde, Edward Hyde'a dönüşüm geri dönülemez ve kalıcı olacaktır.", 'notes': 'irrevocable and permanent: geri dönülemez ve kalıcı.'}, {'id': 484, 'text': 'Within his soul, Edward Hyde is awake, pacing frantically and snarling in hatred against his creator.', 'translation': 'Ruhunun içinde Edward Hyde uyanık; çılgınca volta atıyor ve yaratıcısına karşı nefretle hırlıyor.', 'notes': 'snarling in hatred: nefretle hırlayan.'}, {'id': 485, 'text': 'Hyde loathes Jekyll with demonic fury, yet Hyde is terrified of the gallows and desperate to live.', 'translation': "Hyde şeytani bir öfkeyle Jekyll'dan nefret ediyor fakat Hyde darağacından öd koparcasına korkuyor ve yaşamak için çırpınıyor.", 'notes': 'terrified of the gallows: darağacından ödü kopan.'}, {'id': 486, 'text': 'Jekyll places a crushed phial of prussic acid upon the table, choosing death over eternal imprisonment as a monster.', 'translation': 'Jekyll masanın üzerine ezilmiş bir prusik asit tüpü koyuyor; bir canavar olarak ebediyen hapsolmak yerine ölümü seçiyor.', 'notes': 'eternal imprisonment: ebedi tutsaklık/hapis.'}, {'id': 487, 'text': '"Will Hyde die upon the scaffold? Or will he find the courage to release himself at the last moment?" Jekyll muses.', 'translation': '"Hyde darağacında mı can verecek? Yoksa son anda kendini azat edecek cesareti bulabilecek mi?" diye geçiriyor aklından Jekyll.', 'notes': 'release himself: kendini serbest bırakmak/öldürmek.'}, {'id': 488, 'text': '"God knows; I am careless; this is my true hour of death, and what is to follow concerns another than myself."', 'translation': '"Tanrı bilir; artık umurumda değil; bu benim gerçek ölüm saatimdir ve bundan sonra olacaklar benden başkasını ilgilendirir."', 'notes': 'true hour of death: gerçek ölüm saati.'}, {'id': 489, 'text': '"Here then, as I lay down the pen and proceed to seal up my confession, I bring the life of that unhappy Henry Jekyll to an end."', 'translation': '"İşte bu yüzden kalemi bırakıp itirafımı mühürlemeye geçerken, o bahtsız Henry Jekyll\'ın hayatına bir son veriyorum."', 'notes': 'bring to an end: bir son vermek.'}, {'id': 490, 'text': 'He folds the manuscript, seals it with red wax, and addresses it to his trusted friend Gabriel John Utterson.', 'translation': "Müsveddeyi katlıyor, kırmızı balmumuyla mühürlüyor ve güvenilir dostu Gabriel John Utterson'a adresliyor.", 'notes': 'trusted friend: güvenilir dost.'}, {'id': 491, 'text': 'He lays the new will beside the confession, stripping Hyde of all inheritance and bequeathing his fortune to Utterson.', 'translation': "Hyde'ı tüm mirastan mahrum bırakıp servetini Utterson'a devrederek yeni vasiyetnameyi itirafın yanına koyuyor.", 'notes': 'bequeathing fortune: serveti miras bırakmak.'}, {'id': 492, 'text': "Suddenly, a tremendous crash shakes the cedar door as Poole's heavy axe bites into the wood!", 'translation': "Ansızın Poole'un ağır baltası tahtayı yararken muazzam bir gümbürtü sedir kapıyı sarsıyor!", 'notes': 'axe bites into wood: balta ahşaba saplanıyor.'}, {'id': 493, 'text': '"Jekyll, I demand to see you!" Utterson\'s stern voice shouts from the landing outside.', 'translation': '"Jekyll, seni görmeyi talep ediyorum!" diye bağırıyor dışarıdaki sahanlıktan Utterson\'ın sert sesi.', 'notes': 'stern voice: sert ses.'}, {'id': 494, 'text': "The final pang of metamorphosis strikes Jekyll's heart, twisting his features into the dwarfish snout of Hyde.", 'translation': "Başkalaşımın o son sancısı Jekyll'ın kalbini vuruyor; yüz hatlarını Hyde'ın o cüce çehresine çeviriyor.", 'notes': "snout of Hyde: Hyde'ın hayvanımsı çehresi."}, {'id': 495, 'text': '"Utterson, for God\'s sake, have mercy!" Hyde screams in terrified despair as the axe strikes again.', 'translation': '"Utterson, Tanrı aşkına merhamet et!" diye haykırıyor Hyde balta tekrar vururken dehşet dolu bir çaresizlikle.', 'notes': 'terrified despair: dehşet dolu çaresizlik.'}, {'id': 496, 'text': 'With five thunderous blows, the cedar panels splinter and the heavy lock tears loose from the frame.', 'translation': 'Gök gürültüsünü andıran beş darbeyle sedir paneller parçalanıyor ve ağır kilit çerçeveden kopuyor.', 'notes': 'panels splinter: paneller kıymık kıymık oluyor.'}, {'id': 497, 'text': 'As the door crashes inward, Edward Hyde raises the crushed phial of cyanide to his lips and swallows the poison.', 'translation': 'Kapı içeriye doğru devrilirken Edward Hyde ezilmiş siyanür tüpünü dudaklarına götürüyor ve zehri yutuyor.', 'notes': 'swallows poison: zehri yutuyor.'}, {'id': 498, 'text': 'He collapses upon the carpet, his limbs twitching in the death throes, ending the dark duality forever.', 'translation': 'Halının üzerine yığılıyor; uzuvları ölüm çırpınışlarıyla seğirerek o karanlık ikiliği sonsuza dek noktalıyor.', 'notes': 'ending dark duality: karanlık ikiliği sonlandırmak.'}, {'id': 499, 'text': 'Gabriel John Utterson finishes reading the tragic confession in the quiet solitude of his study, weeping tears of sorrow.', 'translation': 'Gabriel John Utterson çalışma odasının sessiz yalnızlığında hüzün gözyaşları dökerek trajik itirafı okumayı bitiriyor.', 'notes': 'quiet solitude: sessiz yalnızlık.'}, {'id': 500, 'text': 'He closes the manuscript and bows his head, whispering a solemn prayer for the tormented soul of his lost friend.', 'translation': 'Yazmayı kapatıyor ve başını öne eğiyor; kayıp dostunun azap çeken ruhu için vakur bir dua fısıldıyor.', 'notes': 'tormented soul: azap çeken ruh.'}]}]
